    dot.style.left = `${e.clientX - box.left}px`;
    dot.style.top = `${e.clientY - box.top}px`;
    btn.appendChild(dot);
    animate(dot, { scale: [1, 26], opacity: [0.5, 0] }, { duration: 0.65, ease: "easeOut" }).then(() => dot.remove());
  }

  /* --- render ------------------------------------------------------------ */

  return (
    <div className="pbal" ref={rootRef}>
