const ITEMS = [
  "Start", "Type", "Layout", "Color", "Style", "Imagery", "Elements", "Tactics",
  "Motion", "Grid", "Spacing", "Depth", "Voice", "Craft", "Flow", "Ship",
].map((label) => ({ id: label.toLowerCase(), label }));

/* -------------------------------------------------------------- component -- */

/**
 * A list of 3D chips with a real press.
 *
 * Each chip is extruded: its lip is a hard box-shadow `--lift` px deep, and
 * pressing it drives the chip down by exactly that much while the lip shrinks
 * to match — so it travels onto its own edge rather than just shrinking. The
 * soft ground shadow squashes as it goes down. The selected chip stays pressed
 * in, inverted, one pixel proud of the surface.
 *
 * Every transform is Motion's; React only owns which chip is selected.
 */
export default function Chips({
  corner = 20,
  shadow = 50,
  rows = 2,
  theme = "light",
  sound = true,
  defaultValue = "start",
  onChange,
}: ChipsProps) {
  const sfx = useChipSound(sound);
  const rootRef = useRef<HTMLDivElement>(null);
  const chipRefs = useRef(new Map<string, HTMLButtonElement>());
  const [selected, setSelected] = useState<string | null>(defaultValue);
  const selectedRef = useRef(selected);
  selectedRef.current = selected;

  const rowCount = Math.min(4, Math.max(2, Number(rows) || 2));
  const visible = ITEMS.slice(0, rowCount * PER_ROW);

  /* the press travel, from the stylesheet — it is smaller at phone width */
  const edge = useCallback(() => {
    /* declared on the list, which is inside the container its size is queried from */
    const list = rootRef.current?.querySelector(".pchips__list");
    if (!list) return 7;
    return parseFloat(getComputedStyle(list).getPropertyValue("--pchips-edge")) || 7;
  }, []);

  const isOn = (el: HTMLElement) => el.dataset.selected === "true";
  const restY = useCallback((el: HTMLElement) => (isOn(el) ? edge() - DOWN : 0), [edge]);

  const depth = useCallback(
    (el: HTMLElement, px: number, transition: object = SNAP) => {
      const full = edge();
      animate(el, { y: full - px }, transition);
      el.style.setProperty("--lift", `${px}px`);
      const ground = el.querySelector<HTMLElement>(".pchips__ground");
      if (ground) {
        animate(
          ground,
          { opacity: 0.25 + (px / full) * 0.75, scaleX: 0.84 + (px / full) * 0.16 },
          { duration: 0.18 },
        );
      }
    },
    [edge],
  );

  /* every chip straight to its resting state, no animation */
  const settle = useCallback(() => {
    const full = edge();
    chipRefs.current.forEach((el) => {
      const on = isOn(el);
      animate(el, { y: on ? full - DOWN : 0, scale: 1, opacity: 1 }, { duration: 0 });
      el.style.setProperty("--lift", `${on ? DOWN : full}px`);
      const ground = el.querySelector<HTMLElement>(".pchips__ground");
      if (ground) animate(ground, { opacity: on ? 0.36 : 1, scaleX: on ? 0.86 : 1 }, { duration: 0 });
    });
  }, [edge]);

  /* entrance: the rows drop in, chip by chip — and again whenever the row count changes */
  useLayoutEffect(() => {
    settle();
    const chips = visible.map((item) => chipRefs.current.get(item.id)).filter(Boolean) as HTMLButtonElement[];
    chips.forEach((el, i) => {
      el.style.opacity = "0";
      animate(el, { opacity: [0, 1] }, { duration: 0.22, delay: i * 0.055, ease: "easeOut" });
      animate(el, { y: [restY(el) - 28, restY(el)], scale: [0.9, 1] }, { ...ENTRY, delay: i * 0.055 });
    });
    /* a hidden tab never runs those frames — never leave a chip stranded */
    const rescue = window.setTimeout(() => {
      chips.forEach((el) => {
        if (el.style.opacity === "0") el.style.opacity = "";
      });
    }, 1400);
    return () => window.clearTimeout(rescue);
    /* the entrance belongs to the row count, not to every render */
  }, [rowCount]);

  /* keep the press depth right when the chips change size */
  useEffect(() => {
    const root = rootRef.current;
    if (!root || typeof ResizeObserver === "undefined") return;
    let last = edge();
    const observer = new ResizeObserver(() => {
      const next = edge();
      if (next !== last) {
        last = next;
        settle();
      }
    });
    observer.observe(root);
    return () => observer.disconnect();
  }, [edge, settle]);

  function select(id: string) {
    const prev = selectedRef.current;
    const next = prev === id ? null : id;
    selectedRef.current = next;
    setSelected(next);
    if (next) sfx.select();
    else sfx.release();

    chipRefs.current.forEach((el, chipId) => {
      const icon = el.querySelector<SVGElement>(".pchips__icon");
      /* written now rather than on the next render, so `depth` reads the new state */
      el.dataset.selected = String(chipId === next);
      if (chipId === next) {
        depth(el, DOWN);
        animate(el, { scale: [0.97, 1.02, 1] }, { duration: 0.34, ease: [0.2, 0.8, 0.2, 1] });
        if (icon) animate(icon, { rotate: [-14, 0], scale: [1.25, 1] }, SNAP);
      } else if (chipId === prev) {
        depth(el, edge(), POP);
        animate(el, { scale: 1 }, SOFT);
        if (icon) animate(icon, { rotate: 0, scale: 1 }, SOFT);
      }
    });

    onChange?.(next);
  }

  function wire(item: { id: string }) {
    const held = { current: false };
    const el = () => chipRefs.current.get(item.id);
    const icon = () => el()?.querySelector<SVGElement>(".pchips__icon") ?? null;
    const canHover = () => typeof window !== "undefined" && window.matchMedia("(hover: hover)").matches;

    return {
      onPointerEnter: () => {
        const chip = el();
        if (!chip || !canHover() || held.current || isOn(chip)) return;
        sfx.hover();
        animate(chip, { y: -3, scale: 1.015 }, SOFT);
        const i = icon();
        if (i) animate(i, { rotate: -7, scale: 1.14 }, SOFT);
      },
      onPointerLeave: () => {
        const chip = el();
        if (!chip || !canHover() || held.current || isOn(chip)) return;
        animate(chip, { y: 0, scale: 1 }, SOFT);
        const i = icon();
        if (i) animate(i, { rotate: 0, scale: 1 }, SOFT);
      },
      onPointerDown: (event: React.PointerEvent<HTMLButtonElement>) => {
        if (event.button !== 0) return;
        const chip = el();
        if (!chip) return;
        sfx.unlock();
        held.current = true;
        try {
          chip.setPointerCapture(event.pointerId);
        } catch {
          /* capture is a nicety */
        }
        sfx.press();
        depth(chip, DOWN);
        animate(chip, { scale: 0.975 }, SNAP);
        const i = icon();
        if (i) animate(i, { rotate: 0, scale: 0.94 }, SNAP);
      },
      release: () => {
        const chip = el();
        if (!chip || !held.current) return;
        held.current = false;
        if (isOn(chip)) return;
        sfx.release();
        depth(chip, edge(), POP);
        animate(chip, { scale: 1 }, SOFT);
        const i = icon();
        if (i) animate(i, { scale: 1 }, SOFT);
      },
    };
  }

  /* the handlers hold a little per-chip state, so they are made once per chip */
  const handlers = useRef(new Map<string, ReturnType<typeof wire>>());
  const handlersFor = (item: { id: string }) => {
    let h = handlers.current.get(item.id);
    if (!h) {
      h = wire(item);
      handlers.current.set(item.id, h);
    }
    return h;
  };

  function onKeyDown(event: React.KeyboardEvent<HTMLButtonElement>, index: number) {
    const step =
      event.key === "ArrowRight" || event.key === "ArrowDown"
        ? 1
        : event.key === "ArrowLeft" || event.key === "ArrowUp"
          ? -1
          : 0;
    if (!step) return;
    event.preventDefault();
    const next = visible[(index + step + visible.length) % visible.length];
    if (next) chipRefs.current.get(next.id)?.focus();
  }

  const v = Math.min(100, Math.max(0, shadow)) / 100;
  const style = {
    "--corner": `${Math.min(40, Math.max(0, corner))}px`,
    "--shade": (v * 2).toFixed(3),
    "--cast": (0.04 + v * 0.58).toFixed(3),
  } as React.CSSProperties;

  const lines: (typeof ITEMS)[] = [];
  for (let r = 0; r < rowCount; r += 1) lines.push(visible.slice(r * PER_ROW, r * PER_ROW + PER_ROW));

  return (
    <div ref={rootRef} className="pchips" data-theme={theme} style={style}>
      <div className="pchips__list" role="listbox" aria-label="Selection list">
        {lines.map((line, r) => (
          <div className="pchips__row" key={r}>
            {line.map((item) => {
              const index = visible.indexOf(item);
              const h = handlersFor(item);
              const on = selected === item.id;
              return (
                <button
                  key={item.id}
                  ref={(node) => {
                    if (node) chipRefs.current.set(item.id, node);
                    else chipRefs.current.delete(item.id);
                  }}
                  className="pchips__chip"
                  type="button"
                  role="option"
                  aria-selected={on}
                  data-selected={on}
                  onPointerEnter={h.onPointerEnter}
                  onPointerLeave={h.onPointerLeave}
                  onPointerDown={h.onPointerDown}
                  onPointerUp={h.release}
                  onPointerCancel={h.release}
                  onClick={() => select(item.id)}
                  onKeyDown={(event) => onKeyDown(event, index)}
                >
                  <span className="pchips__ground" aria-hidden="true" />
                  <svg className="pchips__icon" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                    {ICONS[item.id]}
                  </svg>
                  <span className="pchips__label">{item.label}</span>
                </button>
              );
            })}
          </div>
        ))}
      </div>
    </div>
  );
}

// Copy Paste Pad — Pin UI (Component)
// npx shadcn@latest add "https://www.pinui.xyz/r/copy-paste-pad.json"

"use client";

import { useEffect, useRef, useState } from "react";
import "./copy-paste-pad.css";

/**
 * Copy Paste Pad — a three-key aluminium macro pad, in 3-D, that copies and
 * pastes the theme.
 *
 * A machined plate on a white wedge, with ⌘ · C · V keycaps, a braided cable
 * and a soft contact shadow, rendered with three.js's WebGPU renderer (it
 * falls back to WebGL 2 on its own). ⌘C copies the current theme; switch the
 * theme, then ⌘V pastes the copied one back. The keys travel on springs —
 * pressed by the physical keyboard or by pointer (tap cmd, then C or V) — and
 * click with synthesised sound. When the theme flips, the one key light
 * travels across the back of the pad, from a warm sun at the back-right to a
 * cool moon at the back-left, so the shadow sweeps over the paper.
 *
 * ⌘C and ⌘V are only taken while the pad is hovered or focused, so the rest of
 * the page copies and pastes as normal. three.js is loaded when the pad
 * mounts, never in the page's first bundle.
 */

export type CopyPastePadProps = {
  theme?: "light" | "dark";
  /** Called by ⌘V with the copied theme. Wire it to your theme switch. */
  onThemeChange?: (theme: "light" | "dark") => void;
  /** The key clicks and the switch tick-tock, synthesised at play time. */
  sound?: boolean;
  /** Fill its container (give it a height) instead of keeping its own 16:10 box. */
  fill?: boolean;
};

const LABEL = { light: "Light", dark: "Dark" } as const;

type Api = {
  setTheme: (dark: boolean) => void;
  dispose: () => void;
};

export default function CopyPastePad({ theme = "light", onThemeChange, sound = true, fill = false }: CopyPastePadProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const stageRef = useRef<HTMLDivElement>(null);
  const apiRef = useRef<Api | null>(null);
  const [ready, setReady] = useState(false);
  const [failed, setFailed] = useState(false);
  const [toast, setToast] = useState<{ text: string; n: number } | null>(null);
  const [isMac, setIsMac] = useState(true);

  /* the props the scene reads live, without rebuilding it */
  const live = useRef({ theme, onThemeChange, sound });
  live.current = { theme, onThemeChange, sound };

  useEffect(() => {
    setIsMac(/Mac|iPhone|iPad/i.test(navigator.platform || navigator.userAgent));
  }, []);

  /* ---------- build the scene once ---------- */
  useEffect(() => {
    const root = rootRef.current;
    const stage = stageRef.current;
    if (!root || !stage) return;
    let cancelled = false;
    let toastTimer = 0;
    const say = (text: string) => {
      clearTimeout(toastTimer);
      setToast((t) => ({ text, n: (t?.n ?? 0) + 1 }));
      toastTimer = window.setTimeout(() => setToast(null), 1600);
    };

    (async () => {
      const THREE = await import("three/webgpu");
      const { RoomEnvironment } = await import("three/examples/jsm/environments/RoomEnvironment.js");
      if (cancelled) return;

      const reduceMotion = matchMedia("(prefers-reduced-motion: reduce)");
      const mac = /Mac|iPhone|iPad/i.test(navigator.platform || navigator.userAgent);
      const MOD = mac ? "⌘" : "Ctrl+";

      /* ── dimensions, 1 = 1 cm ── */
      const MARGIN = 0.42;
      const SPLIT = 0.3;
      const CMD_W = 5.2;
      const SQ_W = 3.26;
      const PAD = { w: 2 * MARGIN + CMD_W + 2 * (SPLIT + SQ_W), d: 4.4, r: 0.62 };
      const BASE = { front: 0.18, back: 0.7, inset: 0.05 };
      const PLATE = { t: 0.26, bevel: 0.055 };
      const TILT = Math.atan((BASE.back - BASE.front) / PAD.d);
      const HOLE_R = 0.4;
      const KEY_GAP = 0.085;
      const KEY = { h: 0.56, rise: 0.24, travel: 0.13, r: 0.34, bevel: 0.075 };
      const innerD = PAD.d - 2 * MARGIN;
      type KeyName = "cmd" | "c" | "v";
      const HOLES = {} as Record<KeyName, { w: number; d: number; x: number }>;
      {
        let x = -PAD.w / 2 + MARGIN;
        for (const [name, w] of [["cmd", CMD_W], ["c", SQ_W], ["v", SQ_W]] as [KeyName, number][]) {
          HOLES[name] = { w, d: innerD, x: x + w / 2 };
          x += w + SPLIT;
        }
      }

      /* ── themes: lighting balanced so a lit, upward surface gets ≈1.0 irradiance ── */
      const DAY = {
        floor: new THREE.Color("#f2c300"),
        bg: new THREE.Color("#f2c300"),
        sky: new THREE.Color("#fffdf7"),
        hemi: 0.56,
        key: { intensity: 0.74, color: new THREE.Color(0xfff4e2), phi: 0.68, theta: 2.14, angle: 1.38, penumbra: 0.2, focus: 0.33 },
        env: 0.36,
        metalEnv: 1.05,
        contact: 0.32,
      };
      const NIGHT = {
        floor: new THREE.Color("#34343a"),
        bg: new THREE.Color("#0f0f11"),
        sky: new THREE.Color("#c9d0e6"),
        hemi: 0.03,
        key: { intensity: 1.6, color: new THREE.Color(0xe3e8f6), phi: 0.52, theta: 2 * Math.PI - 1.9, angle: 0.42, penumbra: 1, focus: 1 },
        env: 0.07,
        metalEnv: 0.38,
        contact: 0.6,
      };

      /* ── quality, per device: phones, tablets and low-core machines get a lighter render ── */
      const coarse = matchMedia("(pointer: coarse)").matches;
      const compact = Math.min(screen.width, screen.height) < 768;
      const lowPower = coarse || compact || (navigator.hardwareConcurrency ?? 8) <= 4;
      const MAX_DPR = lowPower ? 1.5 : 2;
      let pixelRatio = Math.min(window.devicePixelRatio || 1, MAX_DPR);

      /* ── renderer ── */
      const renderer = new THREE.WebGPURenderer({ antialias: true, powerPreference: "high-performance" });
      renderer.setPixelRatio(pixelRatio);
      renderer.setSize(stage.clientWidth || 1, stage.clientHeight || 1);
      renderer.toneMapping = THREE.LinearToneMapping;
      renderer.shadowMap.enabled = true;
      renderer.shadowMap.type = THREE.PCFSoftShadowMap;
      renderer.domElement.tabIndex = -1;
      stage.appendChild(renderer.domElement);

      const scene = new THREE.Scene();
      scene.background = DAY.bg.clone();
      scene.fog = new THREE.Fog(DAY.bg.clone(), 70, 170);

      const camera = new THREE.PerspectiveCamera(28, (stage.clientWidth || 1) / (stage.clientHeight || 1), 0.5, 400);
      const target = new THREE.Vector3(0.4, 0.35, 0);
      const viewDir = new THREE.Vector3(3, 22, 24).normalize();
      const placeCamera = (dist: number) => {
        camera.position.copy(target).addScaledVector(viewDir, dist);
        camera.lookAt(target);
      };

      /* ── helpers ── */
      function roundedRect<T extends InstanceType<typeof THREE.Path>>(path: T, w: number, h: number, r: number, cx = 0, cy = 0): T {
        const x = cx - w / 2;
        const y = cy - h / 2;
        path.moveTo(x + r, y);
        path.lineTo(x + w - r, y);
        path.absarc(x + w - r, y + r, r, -Math.PI / 2, 0, false);
        path.lineTo(x + w, y + h - r);
        path.absarc(x + w - r, y + h - r, r, 0, Math.PI / 2, false);
        path.lineTo(x + r, y + h);
        path.absarc(x + r, y + h - r, r, Math.PI / 2, Math.PI, false);
        path.lineTo(x, y + r);
        path.absarc(x + r, y + r, r, Math.PI, Math.PI * 1.5, false);
        return path;
      }
      /* extrude a flat outline upwards: footprint in XZ, y ∈ [0, height], bevel kept inside the outline */
      const slab = (shape: InstanceType<typeof THREE.Shape>, height: number, bevel = 0, segments = 5) => {
        const g = new THREE.ExtrudeGeometry(shape, {
          depth: height - 2 * bevel,
          bevelEnabled: bevel > 0,
          bevelThickness: bevel,
          bevelSize: bevel,
          bevelSegments: segments,
          curveSegments: 28,
        });
        g.rotateX(-Math.PI / 2);
        g.translate(0, bevel, 0);
        return g;
      };
      const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
      const easeInOut = (t: number) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
      const easeOut = (t: number) => 1 - Math.pow(1 - t, 3);

      /* ── materials ── */
      const M = {
        aluminium: new THREE.MeshPhysicalMaterial({ color: 0xd8d9dc, metalness: 1, roughness: 0.36 }),
        base: new THREE.MeshPhysicalMaterial({ color: 0xefefec, roughness: 0.34, clearcoat: 0.3, clearcoatRoughness: 0.4 }),
        key: new THREE.MeshPhysicalMaterial({ color: 0xefeee9, roughness: 0.62, specularIntensity: 0.6 }),
        well: new THREE.MeshStandardMaterial({ color: 0x1e1e21, roughness: 0.9 }),
        cable: new THREE.MeshPhysicalMaterial({ color: 0xf5f5f3, roughness: 0.4, clearcoat: 0.25, clearcoatRoughness: 0.5 }),
      };

      /* ── the pad ── */
      const rig = new THREE.Group();
      rig.rotation.y = 0.3;
      scene.add(rig);

      /* the white wedge: flat footprint, top sloping up from front to back */
      {
        const w = PAD.w - 2 * BASE.inset;
        const d = PAD.d - 2 * BASE.inset;
        const g = slab(roundedRect(new THREE.Shape(), w, d, PAD.r - BASE.inset), 1);
        const pos = g.attributes.position;
        for (let i = 0; i < pos.count; i++) {
          if (pos.getY(i) > 0.5) pos.setY(i, lerp(BASE.front, BASE.back, (PAD.d / 2 - pos.getZ(i)) / PAD.d));
        }
        const base = new THREE.Mesh(g, M.base);
        base.castShadow = base.receiveShadow = true;
        rig.add(base);
      }

      /* the tilted deck: the plate and the keys follow the wedge's slope */
      const deck = new THREE.Group();
      deck.position.y = (BASE.front + BASE.back) / 2;
      deck.rotation.x = TILT;
      rig.add(deck);
      {
        const b = PLATE.bevel;
        const shape = roundedRect(new THREE.Shape(), PAD.w - 2 * b, PAD.d - 2 * b, PAD.r - b);
        for (const h of Object.values(HOLES)) shape.holes.push(roundedRect(new THREE.Path(), h.w + 2 * b, h.d + 2 * b, HOLE_R + b, h.x, 0));
        const plate = new THREE.Mesh(slab(shape, PLATE.t, b, 6), M.aluminium);
        plate.castShadow = plate.receiveShadow = true;
        deck.add(plate);
        for (const h of Object.values(HOLES)) {
          const well = new THREE.Mesh(new THREE.ShapeGeometry(roundedRect(new THREE.Shape(), h.w, h.d, HOLE_R, h.x, 0), 16), M.well);
          well.rotation.x = -Math.PI / 2;
          well.position.y = 0.004;
          well.receiveShadow = true;
          deck.add(well);
        }
      }

      /* ── keycap legends, painted on canvases ── */
      const PX = 160;
      const drawCommandGlyph = (ctx: CanvasRenderingContext2D, cx: number, cy: number, size: number, lineWidth: number) => {
        const s = size * 0.17;
        const r = size * 0.16;
        ctx.save();
        ctx.translate(cx, cy);
        ctx.lineWidth = lineWidth;
        ctx.lineCap = "round";
        ctx.lineJoin = "round";
        ctx.beginPath();
        for (const [sx, sy] of [[1, 1], [1, -1], [-1, 1], [-1, -1]]) {
          ctx.save();
          ctx.scale(sx, sy);
          ctx.moveTo(0, s);
          ctx.lineTo(s + r, s);
          ctx.arc(s + r, s + r, r, -Math.PI / 2, Math.PI, false);
          ctx.lineTo(s, 0);
          ctx.restore();
        }
        ctx.stroke();
        ctx.restore();
      };
      const letter = (ctx: CanvasRenderingContext2D, w: number, h: number, char: string) => {
        ctx.font = `${Math.round(h * 0.3)}px "Varela Round", "Arial Rounded MT Bold", sans-serif`;
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.fillText(char, w * 0.5, h * 0.5);
      };
      const LEGENDS: Record<KeyName, (ctx: CanvasRenderingContext2D, w: number, h: number) => void> = {
        cmd: (ctx, w, h) => {
          ctx.font = `${Math.round(h * 0.23)}px "Varela Round", "Arial Rounded MT Bold", sans-serif`;
          ctx.textBaseline = "alphabetic";
          ctx.fillText("cmd", w * 0.085, h * 0.82);
          drawCommandGlyph(ctx, w * 0.84, h * 0.3, h * 0.27, h * 0.021);
        },
        c: (ctx, w, h) => letter(ctx, w, h, "C"),
        v: (ctx, w, h) => letter(ctx, w, h, "V"),
      };
      const legendTexture = (w: number, h: number, draw: (ctx: CanvasRenderingContext2D, w: number, h: number) => void) => {
        const canvas = document.createElement("canvas");
        canvas.width = Math.round(w * PX);
        canvas.height = Math.round(h * PX);
        const ctx = canvas.getContext("2d")!;
        ctx.fillStyle = ctx.strokeStyle = "#fff";
        draw(ctx, canvas.width, canvas.height);
        const tex = new THREE.CanvasTexture(canvas);
        tex.colorSpace = THREE.SRGBColorSpace;
        tex.anisotropy = 8;
        return tex;
      };

      /* ── keys ── */
      type Key = { mesh: InstanceType<typeof THREE.Mesh>; down: boolean; pos: number; vel: number };
      const keys = {} as Record<KeyName, Key>;
      const keyMeshes: InstanceType<typeof THREE.Mesh>[] = [];
      const restY = PLATE.t + KEY.rise - KEY.h;
      const buildKey = (name: KeyName) => {
        const h = HOLES[name];
        const w = h.w - 2 * KEY_GAP;
        const d = h.d - 2 * KEY_GAP;
        const b = KEY.bevel;
        /* each keycap owns its material, so no two keys share stale per-object render state */
        const mesh = new THREE.Mesh(slab(roundedRect(new THREE.Shape(), w - 2 * b, d - 2 * b, KEY.r - b), KEY.h, b, 6), M.key.clone());
        mesh.position.set(h.x, restY, 0);
        mesh.castShadow = mesh.receiveShadow = true;
        mesh.userData.key = name;
        const face = { w: w - 2 * b, d: d - 2 * b };
        const legend = new THREE.Mesh(
          new THREE.PlaneGeometry(face.w, face.d),
          new THREE.MeshStandardMaterial({
            color: 0x8f8f94,
            map: legendTexture(face.w, face.d, LEGENDS[name]),
            transparent: true,
            roughness: 0.6,
            polygonOffset: true,
            polygonOffsetFactor: -2,
            depthWrite: false,
          }),
        );
        legend.rotation.x = -Math.PI / 2;
        legend.position.y = KEY.h + 0.003;
        mesh.add(legend);
        deck.add(mesh);
        keyMeshes.push(mesh);
        keys[name] = { mesh, down: false, pos: 0, vel: 0 };
      };

      /* ── cable ── */
      {
        const R = 0.2;
        const dx = -PAD.w / 2 + 2.2 + 2.6;
        const curve = new THREE.CatmullRomCurve3(
          [
            [-2.6, 0.42, -1.9],
            [-2.6, 0.4, -2.75],
            [-2.85, 0.26, -3.7],
            [-4.1, R, -4.9],
            [-6.8, R, -5.9],
            [-10.5, R, -6.4],
            [-16, R, -6.7],
            [-34, R, -7.4],
          ].map(([x, y, z]) => new THREE.Vector3(x + dx, y, z)),
          false,
          "centripetal",
        );
        const cable = new THREE.Mesh(new THREE.TubeGeometry(curve, 320, R, 24, false), M.cable);
        cable.castShadow = cable.receiveShadow = true;
        rig.add(cable);
        const relief = new THREE.Mesh(new THREE.CylinderGeometry(0.27, 0.3, 0.9, 32), M.cable);
        const start = curve.getPointAt(0.012);
        const tangent = curve.getTangentAt(0.012);
        relief.position.copy(start).addScaledVector(tangent, 0.2);
        relief.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), tangent);
        relief.castShadow = true;
        rig.add(relief);
      }

      /* ── floor and contact shadow ── */
      const grainTexture = () => {
        const size = 256;
        const canvas = document.createElement("canvas");
        canvas.width = canvas.height = size;
        const ctx = canvas.getContext("2d")!;
        const img = ctx.createImageData(size, size);
        for (let i = 0; i < img.data.length; i += 4) {
          const v = 244 + Math.random() * 11;
          img.data[i] = img.data[i + 1] = img.data[i + 2] = v;
          img.data[i + 3] = 255;
        }
        ctx.putImageData(img, 0, 0);
        for (let i = 0; i < 26; i++) {
          ctx.fillStyle = `rgba(255,255,255,${0.5 + Math.random() * 0.4})`;
          ctx.beginPath();
          ctx.arc(Math.random() * size, Math.random() * size, 0.5 + Math.random() * 0.8, 0, Math.PI * 2);
          ctx.fill();
        }
        const tex = new THREE.CanvasTexture(canvas);
        tex.colorSpace = THREE.SRGBColorSpace;
        tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
        tex.repeat.set(60, 60);
        return tex;
      };
      const floorMat = new THREE.MeshStandardMaterial({ color: DAY.floor.clone(), roughness: 0.93, map: grainTexture() });
      const floor = new THREE.Mesh(new THREE.PlaneGeometry(600, 600), floorMat);
      floor.rotation.x = -Math.PI / 2;
      floor.receiveShadow = true;
      scene.add(floor);

      const contactTexture = () => {
        const canvas = document.createElement("canvas");
        canvas.width = 512;
        canvas.height = 300;
        const ctx = canvas.getContext("2d")!;
        ctx.filter = "blur(18px)";
        ctx.fillStyle = "#000";
        ctx.beginPath();
        ctx.roundRect(70, 70, 372, 160, 30);
        ctx.fill();
        const tex = new THREE.CanvasTexture(canvas);
        tex.colorSpace = THREE.SRGBColorSpace;
        return tex;
      };
      const contact = new THREE.Mesh(
        new THREE.PlaneGeometry(PAD.w * (512 / 372), PAD.d * (300 / 160)),
        new THREE.MeshBasicMaterial({ map: contactTexture(), transparent: true, depthWrite: false, opacity: DAY.contact, toneMapped: false }),
      );
      contact.rotation.x = -Math.PI / 2;
      contact.position.y = 0.01;
      contact.renderOrder = -1;
      rig.add(contact);

      /* ── lights: one shadow-casting key light that travels with the theme ── */
      const hemi = new THREE.HemisphereLight(DAY.sky.clone(), DAY.floor.clone(), DAY.hemi);
      hemi.position.set(0, 1000, 0);
      scene.add(hemi);
      const keyLight = new THREE.SpotLight(0xffffff, 1, 0, 1, 0.5, 0);
      keyLight.castShadow = true;
      keyLight.shadow.mapSize.setScalar(lowPower ? 1024 : 2048);
      keyLight.shadow.camera.near = 1;
      keyLight.shadow.camera.far = 60;
      keyLight.shadow.bias = -0.0004;
      keyLight.shadow.normalBias = 0.02;
      keyLight.shadow.radius = 5;
      keyLight.target.position.set(0, 0, 0);
      scene.add(keyLight, keyLight.target);
      const KEY_DIST = 21;
      const tmp = new THREE.Color();
      let themeT = live.current.theme === "dark" ? 1 : 0;
      let themeAnim: { from: number; to: number; start: number; dur: number } | null = null;
      const applySceneTheme = (t: number) => {
        tmp.lerpColors(DAY.floor, NIGHT.floor, t);
        floorMat.color.copy(tmp);
        hemi.groundColor.copy(tmp);
        hemi.color.lerpColors(DAY.sky, NIGHT.sky, t);
        hemi.intensity = lerp(DAY.hemi, NIGHT.hemi, t);
        tmp.lerpColors(DAY.bg, NIGHT.bg, t);
        (scene.background as InstanceType<typeof THREE.Color>).copy(tmp);
        scene.fog!.color.copy(tmp);
        const a = DAY.key;
        const b = NIGHT.key;
        /* it rises a little mid-arc so the light passes over the pad, not through it */
        const phi = lerp(a.phi, b.phi, t) - Math.sin(Math.PI * t) * 0.18;
        keyLight.position.setFromSphericalCoords(KEY_DIST, phi, lerp(a.theta, b.theta, t));
        keyLight.color.lerpColors(a.color, b.color, t);
        keyLight.intensity = lerp(a.intensity, b.intensity, t);
        keyLight.angle = lerp(a.angle, b.angle, t);
        keyLight.penumbra = lerp(a.penumbra, b.penumbra, t);
        keyLight.shadow.focus = lerp(a.focus, b.focus, t);
        scene.environmentIntensity = lerp(DAY.env, NIGHT.env, t);
        M.aluminium.envMapIntensity = lerp(DAY.metalEnv, NIGHT.metalEnv, t);
        (contact.material as InstanceType<typeof THREE.MeshBasicMaterial>).opacity = lerp(DAY.contact, NIGHT.contact, t);
      };

      /* ── sound, synthesised ── */
      let audio: AudioContext | null = null;
      const audioCtx = () => {
        try {
          audio ??= new AudioContext();
          if (audio.state === "suspended") void audio.resume();
          return audio;
        } catch {
          return null;
        }
      };
      const click = ({ freq = 2600, gain = 0.45, thump = true, at = 0 } = {}) => {
        if (!live.current.sound) return;
        const ac = audioCtx();
        if (!ac) return;
        const t = ac.currentTime + at;
        const len = Math.floor(ac.sampleRate * 0.03);
        const buf = ac.createBuffer(1, len, ac.sampleRate);
        const data = buf.getChannelData(0);
        for (let i = 0; i < len; i++) data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / len, 5);
        const src = ac.createBufferSource();
        src.buffer = buf;
        const bp = ac.createBiquadFilter();
        bp.type = "bandpass";
        bp.frequency.value = freq;
        bp.Q.value = 1.1;
        const g = ac.createGain();
        g.gain.value = gain;
        src.connect(bp).connect(g).connect(ac.destination);
        src.start(t);
        if (thump) {
          const o = ac.createOscillator();
          const og = ac.createGain();
          o.frequency.setValueAtTime(180, t);
          o.frequency.exponentialRampToValueAtTime(65, t + 0.05);
          og.gain.setValueAtTime(0.22, t);
          og.gain.exponentialRampToValueAtTime(0.001, t + 0.07);
          o.connect(og).connect(ac.destination);
          o.start(t);
          o.stop(t + 0.08);
        }
      };
      const keyDownSound = () => click({ freq: 2400, gain: 0.5 });
      const keyUpSound = () => click({ freq: 3600, gain: 0.22, thump: false });
      const switchSound = () => {
        click({ freq: 1800, gain: 0.35 });
        click({ freq: 3200, gain: 0.18, thump: false, at: 0.045 });
      };

      /* ── copy and paste the theme ── */
      let copied: "light" | "dark" | null = null;
      const copyTheme = () => {
        copied = live.current.theme;
        say(`Copied · ${LABEL[copied]} theme`);
      };
      const pasteTheme = () => {
        if (!copied) return say(`Nothing copied yet — press ${MOD}C first`);
        if (copied !== live.current.theme) live.current.onThemeChange?.(copied);
        say(`Pasted · ${LABEL[copied]} theme`);
      };
      const ACTIONS: Partial<Record<KeyName, () => void>> = { c: copyTheme, v: pasteTheme };

      /* ── pressing keys ── */
      let cmdLatchUntil = 0;
      const LATCH_MS = 1400;
      const pressKey = (name: KeyName) => {
        const k = keys[name];
        if (!k || k.down) return;
        k.down = true;
        keyDownSound();
      };
      const releaseKey = (name: KeyName) => {
        const k = keys[name];
        if (!k || !k.down) return;
        k.down = false;
        keyUpSound();
      };

      const raycaster = new THREE.Raycaster();
      const ndc = new THREE.Vector2();
      const canvas = renderer.domElement;
      const pick = (e: PointerEvent): KeyName | null => {
        const rect = canvas.getBoundingClientRect();
        ndc.set(((e.clientX - rect.left) / rect.width) * 2 - 1, -((e.clientY - rect.top) / rect.height) * 2 + 1);
        raycaster.setFromCamera(ndc, camera);
        let obj: InstanceType<typeof THREE.Object3D> | null = raycaster.intersectObjects(keyMeshes, true)[0]?.object ?? null;
        while (obj && !obj.userData.key) obj = obj.parent;
        return (obj?.userData.key as KeyName) ?? null;
      };

      let pointerKey: { name: KeyName; id: number } | null = null;
      const onDown = (e: PointerEvent) => {
        const name = pick(e);
        if (!name) return;
        pointerKey = { name, id: e.pointerId };
        try {
          canvas.setPointerCapture(e.pointerId);
        } catch {}
        pressKey(name);
        const action = ACTIONS[name];
        if (action) {
          if (performance.now() < cmdLatchUntil || keys.cmd.down) {
            cmdLatchUntil = 0;
            action();
          } else {
            say(`Tap cmd first, then ${name.toUpperCase()}, to ${name === "c" ? "copy" : "paste"} the theme`);
          }
        }
      };
      const endPointer = (e: PointerEvent) => {
        if (!pointerKey || e.pointerId !== pointerKey.id) return;
        releaseKey(pointerKey.name);
        if (pointerKey.name === "cmd") cmdLatchUntil = performance.now() + LATCH_MS;
        pointerKey = null;
      };
      const onMove = (e: PointerEvent) => {
        if (pointerKey) return;
        canvas.style.cursor = pick(e) ? "pointer" : "default";
      };
      canvas.addEventListener("pointerdown", onDown);
      canvas.addEventListener("pointerup", endPointer);
      canvas.addEventListener("pointercancel", endPointer);
      canvas.addEventListener("pointermove", onMove);

      /* the physical keyboard drives the same keys — only while the pad is hovered or focused */
      let hovered = false;
      const armed = () => hovered || root.contains(document.activeElement);
      const onEnter = () => (hovered = true);
      const onLeave = () => (hovered = false);
      root.addEventListener("pointerenter", onEnter);
      root.addEventListener("pointerleave", onLeave);
      const isModifier = (e: KeyboardEvent) => e.key === "Meta" || e.key === "Control";
      const LETTER_CODES: Record<string, KeyName> = { KeyC: "c", KeyV: "v" };
      const onKeyDown = (e: KeyboardEvent) => {
        if (!armed()) return;
        if (isModifier(e)) pressKey("cmd");
        const name = LETTER_CODES[e.code];
        if (!name) return;
        const withMod = e.metaKey || e.ctrlKey;
        if (withMod) e.preventDefault();
        if (e.repeat) return;
        pressKey(name);
        if (withMod) {
          ACTIONS[name]?.();
          /* macOS swallows keyup for keys pressed while ⌘ is held */
          if (e.metaKey) setTimeout(() => releaseKey(name), 150);
        }
      };
      const releaseAll = () => (Object.keys(keys) as KeyName[]).forEach(releaseKey);
      const onKeyUp = (e: KeyboardEvent) => {
        if (isModifier(e)) releaseAll();
        const name = LETTER_CODES[e.code];
        if (name) releaseKey(name);
      };
      addEventListener("keydown", onKeyDown);
      addEventListener("keyup", onKeyUp);
      addEventListener("blur", releaseAll);

      /* ── framing ── */
      const fitDistance = () => {
        const vfov = THREE.MathUtils.degToRad(camera.fov);
        const hfov = 2 * Math.atan(Math.tan(vfov / 2) * camera.aspect);
        const scale = PAD.w / 9.6;
        /* landscape: the pad takes about 60% of the width, as in the product shot;
           portrait (a phone): it is framed to about 85%, so it still reads at arm's length */
        const span = camera.aspect < 1 ? PAD.w * 1.18 : 15.5 * scale;
        return Math.max(camera.aspect < 1 ? 0 : 31 * scale, span / 2 / Math.tan(hfov / 2));
      };
      let intro: { start: number; dur: number; from: number; to: number } | null = null;
      /* a frame is only drawn when something changed: an idle pad costs nothing */
      let dirty = true;
      const resize = () => {
        const w = stage.clientWidth;
        const h = stage.clientHeight;
        if (!w || !h) return;
        camera.aspect = w / h;
        camera.updateProjectionMatrix();
        renderer.setSize(w, h);
        if (intro) intro.to = fitDistance();
        else placeCamera(fitDistance());
        dirty = true;
      };
      let resizeFrame = 0;
      const ro = new ResizeObserver(() => {
        cancelAnimationFrame(resizeFrame);
        resizeFrame = requestAnimationFrame(resize);
      });
      ro.observe(stage);

      /* ── the loop ── */
      const clock = new THREE.Clock();
      const SPRING_K = 1500;
      const SPRING_C = 2 * Math.sqrt(SPRING_K) * 0.6;
      /* adaptive resolution: if animated frames run slow, step the pixel ratio down (never back up) */
      let slowSum = 0;
      let slowN = 0;
      const tick = () => {
        const dt = Math.min(clock.getDelta(), 1 / 30);
        const now = performance.now();
        let moving = false;
        for (const [name, k] of Object.entries(keys) as [KeyName, Key][]) {
          const latched = name === "cmd" && now < cmdLatchUntil;
          const goal = k.down ? KEY.travel : latched ? KEY.travel * 0.45 : 0;
          if (Math.abs(goal - k.pos) < 1e-5 && Math.abs(k.vel) < 1e-4) {
            if (k.pos !== goal) {
              k.pos = goal;
              k.vel = 0;
              k.mesh.position.y = restY - k.pos;
              dirty = true;
            }
            continue;
          }
          for (let i = 0; i < 4; i++) {
            const h = dt / 4;
            k.vel += (SPRING_K * (goal - k.pos) - SPRING_C * k.vel) * h;
            k.pos += k.vel * h;
          }
          k.mesh.position.y = restY - k.pos;
          moving = true;
        }
        if (themeAnim) {
          const p = Math.min(1, (now - themeAnim.start) / themeAnim.dur);
          themeT = lerp(themeAnim.from, themeAnim.to, easeInOut(p));
          applySceneTheme(themeT);
          moving = true;
          if (p === 1) themeAnim = null;
        }
        if (intro) {
          const p = Math.min(1, (now - intro.start) / intro.dur);
          placeCamera(lerp(intro.from, intro.to, easeOut(p)));
          moving = true;
          if (p === 1) intro = null;
        }
        if (moving) {
          slowSum += dt;
          if (++slowN === 24) {
            if (slowSum / slowN > 1 / 36 && pixelRatio > 1) {
              pixelRatio = Math.max(1, pixelRatio - 0.25);
              renderer.setPixelRatio(pixelRatio);
              resize();
            }
            slowSum = 0;
            slowN = 0;
          }
        }
        if (!moving && !dirty) return;
        dirty = false;
        renderer.render(scene, camera);
      };

      /* ── run only while it can be seen ── */
      let onScreen = true;
      let running = false;
      const run = () => {
        const should = onScreen && !document.hidden;
        if (should === running) return;
        running = should;
        if (should) {
          clock.getDelta();
          dirty = true;
        }
        renderer.setAnimationLoop(should ? tick : null);
      };
      const io = new IntersectionObserver(([e]) => {
        onScreen = e.isIntersecting;
        run();
      });
      const onVisibility = () => run();

      /* ── boot ── */
      try {
        await renderer.init();
      } catch (err) {
        console.error(err);
        if (!cancelled) setFailed(true);
        return;
      }
      if (cancelled) {
        renderer.dispose();
        return;
      }
      const pmrem = new THREE.PMREMGenerator(renderer);
      scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
      M.aluminium.envMap = scene.environment;

      /* the legends need the rounded face loaded before they are painted */
      try {
        await Promise.race([document.fonts.load('64px "Varela Round"'), new Promise((r) => setTimeout(r, 2500))]);
      } catch {}
      if (cancelled) return;
      (Object.keys(HOLES) as KeyName[]).forEach(buildKey);

      resize();
      /* the theme may have changed while three.js was loading: start in the current one */
      themeT = live.current.theme === "dark" ? 1 : 0;
      applySceneTheme(themeT);
      const dist = fitDistance();
      placeCamera(reduceMotion.matches ? dist : dist * 1.12);
      /* compile every shader up front, off the main thread where the backend allows,
         so the first frames are not a burst of synchronous pipeline builds */
      try {
        await renderer.compileAsync(scene, camera);
      } catch {}
      if (cancelled) return;
      if (!reduceMotion.matches) {
        /* a short dolly-in on the same angle: the shot settles rather than swings */
        intro = { start: performance.now() + 150, dur: 1400, from: dist * 1.12, to: dist };
      }
      io.observe(root);
      document.addEventListener("visibilitychange", onVisibility);
      /* create the audio context in idle time (it starts suspended until a gesture resumes it),
         so the first click or theme change does not pay for it */
      const idle = window.requestIdleCallback ?? ((cb: () => void) => window.setTimeout(cb, 400));
      idle(() => {
        if (cancelled || audio) return;
        try {
          audio = new AudioContext();
        } catch {}
      });
      run();
      requestAnimationFrame(() => !cancelled && setReady(true));

      apiRef.current = {
        setTheme: (dark) => {
          const to = dark ? 1 : 0;
          if (to === (themeAnim ? themeAnim.to : themeT)) return;
          switchSound();
          if (reduceMotion.matches) {
            themeAnim = null;
            themeT = to;
            applySceneTheme(to);
            dirty = true;
          } else {
            themeAnim = { from: themeT, to, start: performance.now(), dur: 1100 };
          }
        },
        dispose: () => {
          renderer.setAnimationLoop(null);
          ro.disconnect();
          io.disconnect();
          cancelAnimationFrame(resizeFrame);
          document.removeEventListener("visibilitychange", onVisibility);
          canvas.removeEventListener("pointerdown", onDown);
          canvas.removeEventListener("pointerup", endPointer);
          canvas.removeEventListener("pointercancel", endPointer);
          canvas.removeEventListener("pointermove", onMove);
          root.removeEventListener("pointerenter", onEnter);
          root.removeEventListener("pointerleave", onLeave);
          removeEventListener("keydown", onKeyDown);
          removeEventListener("keyup", onKeyUp);
          removeEventListener("blur", releaseAll);
          scene.traverse((o) => {
            const mesh = o as InstanceType<typeof THREE.Mesh>;
            mesh.geometry?.dispose?.();
            const mats = Array.isArray(mesh.material) ? mesh.material : mesh.material ? [mesh.material] : [];
            mats.forEach((m) => {
              (m as InstanceType<typeof THREE.MeshStandardMaterial>).map?.dispose();
              m.dispose();
            });
          });
          pmrem.dispose();
          renderer.dispose();
          canvas.remove();
          void audio?.close();
        },
      };
    })().catch((err) => {
      console.error(err);
      if (!cancelled) setFailed(true);
    });

    return () => {
      cancelled = true;
      clearTimeout(toastTimer);
      apiRef.current?.dispose();
      apiRef.current = null;
    };
  }, []);

  /* the site's theme drives the scene: the key light travels from sun to moon */
  useEffect(() => {
    apiRef.current?.setTheme(theme === "dark");
  }, [theme]);

  const mod = isMac ? "⌘" : "Ctrl";

  return (
    <div
      ref={rootRef}
      className="pcpp"
      data-theme={theme}
      data-fill={fill || undefined}
      tabIndex={0}
      role="application"
      aria-label={`3-D macro pad with cmd, C and V keys. Press ${mod} and C to copy the theme, then ${mod} and V to paste it.`}
    >
      <div ref={stageRef} className="pcpp__stage" data-ready={ready || undefined} />

      <div className="pcpp__toast pcpp__glass" data-show={toast ? true : undefined} role="status" aria-live="polite">
        {toast?.text}
      </div>

      {failed && (
        <p className="pcpp__error">
          This browser couldn&rsquo;t start the 3-D renderer (WebGPU or WebGL 2). Try a current Chrome, Edge, Safari or Firefox.
        </p>
      )}
    </div>
  );
}

// Desk Computer — Pin UI (Component)
// npx shadcn@latest add "https://www.pinui.xyz/r/desk-computer.json"

"use client";

import { useEffect, useRef, useState } from "react";
import { mountDeskComputer, type DeskEngine } from "./desk-computer-engine";
import "./desk-computer.css";

/**
 * Desk Computer — an isometric late-90s desk computer you can use.
 *
 * A beige CRT on a swivel base showing a browser with a search box, a
 * mid-tower with a CD-ROM and a floppy drive, a 104-key keyboard, a ball mouse
 * on its pad, a speaker and a CD-R in its jewel case, joined by cables. It is
 * one SVG, built in true isometric with the Anatomy kit, and every colour on
 * it is a token with a value for each theme.
 *
 * Focus it and type: the keys go down and the text lands in the search box;
 * Enter searches and the hard-drive LED flickers. Drag the mouse around its
 * pad — its cable follows and the cursor moves on the CRT. Click the jewel
 * case and the drive's tray slides out, the disc flies in and AutoPlay opens;
 * click the drive to eject it. Escape or the monitor's power button collapses
 * the picture to a line and a dot. It assembles itself on arrival and on every
 * theme change, and while nobody is touching it, it gives itself a tour.
 *
 * The drawing is ~480KB of SVG, so it is fetched at mount (from `src`) rather
 * than shipped in the bundle; desk-computer-engine.ts is everything it does.
 */

export type DeskComputerProps = {
  theme?: "light" | "dark";
  /** Key clicks and the CRT's power-on hum and power-off zap, synthesised. Only your own input makes sound. */
  sound?: boolean;
  /** Fill the container edge to edge; otherwise it keeps the drawing's own 1000:760 shape. */
  fill?: boolean;
  /** Where the drawing is served from. */
  src?: string;
};

export default function DeskComputer({ theme = "light", sound = true, fill = false, src = "/library/desk-computer.svg" }: DeskComputerProps) {
  const stageRef = useRef<HTMLDivElement>(null);
  const artRef = useRef<HTMLDivElement>(null);
  const statusRef = useRef<HTMLSpanElement>(null);
  const engineRef = useRef<DeskEngine | null>(null);
  const soundRef = useRef(sound);
  soundRef.current = sound;
  const [state, setState] = useState<"loading" | "ready" | "failed">("loading");

  /* fetch the drawing, inline it, and start the engine on it */
  useEffect(() => {
    const stage = stageRef.current;
    const art = artRef.current;
    const status = statusRef.current;
    if (!stage || !art || !status) return;
    const abort = new AbortController();
    let engine: DeskEngine | null = null;
    setState("loading");
    fetch(src, { signal: abort.signal })
      .then((r) => {
        if (!r.ok) throw new Error(`${r.status} ${r.statusText}`);
        return r.text();
      })
      .then((markup) => {
        if (abort.signal.aborted) return;
        art.innerHTML = markup;
        const svg = art.querySelector("svg");
        if (!svg) throw new Error("the drawing has no <svg>");
        engine = mountDeskComputer({ stage, svg, status, muted: !soundRef.current });
        engineRef.current = engine;
        setState("ready");
      })
      .catch((err: unknown) => {
        if (abort.signal.aborted) return;
        console.error("[DeskComputer]", err);
        setState("failed");
      });
    return () => {
      abort.abort();
      engine?.destroy();
      engineRef.current = null;
      art.innerHTML = "";
    };
  }, [src]);

  useEffect(() => {
    engineRef.current?.setMuted(!sound);
  }, [sound]);

  /* the system assembles itself again under the new light, as the figure always has */
  const firstTheme = useRef(true);
  useEffect(() => {
    if (firstTheme.current) {
      firstTheme.current = false;
      return;
    }
    engineRef.current?.replayIntro();
  }, [theme]);

  return (
    <div className="pdesk" data-theme={theme} data-fill={fill || undefined} data-ready={state === "ready" || undefined}>
      <div
        ref={stageRef}
        className="pdesk__stage"
        tabIndex={0}
        role="group"
        aria-label="Desk computer. Type to search on its screen; Enter searches; Escape or the monitor's power button switches the screen. Drag the mouse; click the CD to load it."
      >
        <div ref={artRef} />
        <span ref={statusRef} className="pdesk__sr" role="status" aria-live="polite" />
      </div>

      {state === "failed" && <p className="pdesk__error">The drawing couldn&rsquo;t be loaded from {src}.</p>}
    </div>
  );
}

// Dynamic Drop Zone — Pin UI (Component)
// npx shadcn@latest add "https://www.pinui.xyz/r/dynamic-drop-zone.json"

"use client";

import {
  useEffect,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
  type DragEvent,
  type KeyboardEvent as ReactKeyboardEvent,
  type PointerEvent as ReactPointerEvent,
  type Ref,
  type RefObject,
} from "react";
import { createPortal } from "react-dom";
import {
  animate,
  AnimatePresence,
  motion,
  useAnimate,
  useMotionValue,
  useSpring,
  useTransform,
  type AnimationPlaybackControls,
  type MotionValue,
  type TargetAndTransition,
  type Transition,
} from "motion/react";
import "./dynamic-drop-zone.css";

/**
 * Dynamic Drop Zone — a file drop zone that turns into a black hole.
 *
 * Carry a file over it and the paper dims through grey into ink: eight dashed
 * rings fall into a tunnel that bends toward the pointer, inner rings leaning
 * furthest, while debris spirals in from the rim. Drop it and the hole pulls
 * itself in, swallows the file, flashes back out to paper — and the innermost
 * ring becomes an upload pill with the others stacked behind it like drawers,
 * a spinner that shrinks into a drawn check, then a reset.
 *
 * It takes real files from the desktop, and carries a demo file of its own,
 * centred under the zone, so it can be tried without one: drag it with a
 * mouse, pen or finger, or focus it and press Enter to watch the drag played
 * for you. There is no panel around it — it sits on whatever it is put on.
 */

export type DynamicDropZoneProps = {
  theme?: "light" | "dark";
  /** The zone's corner radius, 0–40px. */
  corner?: number;
  /** How long the spinner runs before the check lands, in ms. */
  uploadMs?: number;
  /** The draggable demo file under the zone. */
  demoFile?: boolean;
  /** Fired with the files dropped from the desktop — the demo file sends none. */
  onDrop?: (files: File[]) => void;
};

type Phase = "idle" | "over" | "collapse" | "uploading" | "done";

/* lets something other than a native file drag — the demo file — drive the zone */
type ZoneHandle = {
  /* the pointer moved while carrying a file; true while it is over the zone */
  dragMove(x: number, y: number): boolean;
  /* the pointer was released; true when the zone took the file */
  dragEnd(x: number, y: number): boolean;
  /* where a dropped file is swallowed, in viewport coordinates */
  center(): { x: number; y: number } | null;
};

const W = 380;
const H = 280;
const RINGS = 8;
/* the magnet: how far the inner rings may lean toward the pointer */
const PULL_X = 46;
const PULL_Y = 34;
const COLLAPSE_MS = 380;
const DONE_MS = 1700;

const morph: Transition = { type: "spring", visualDuration: 0.5, bounce: 0.18 };
const quick: Transition = { duration: 0.2, ease: [0.25, 0.1, 0.25, 1] };

/*
 * The colours the zone animates between. Motion tweens these as literal
 * values, so they live here rather than in the stylesheet. Every box-shadow
 * keeps the same four-layer shape so it can tween.
 */
type Palette = {
  card: string;
  cardClear: string;
  cardFade: string;
  flash: string;
  flashDeep: string;
  hole: string;
  restShadow: string;
  holeShadow: string;
  ringFirst: string;
  ring: string;
  ringAlpha: number;
  ringStep: number;
  stack: string;
  stackAlpha: number;
  pill: string;
  pillBorder: string;
  text: string;
};

const PALETTES: Record<"light" | "dark", Palette> = {
  light: {
    card: "#ffffff",
    cardClear: "rgba(255, 255, 255, 0)",
    cardFade: "rgba(255, 255, 255, 0.7)",
    flash: "#bfbfc2",
    flashDeep: "#3b3b3f",
    hole: "#030303",
    restShadow:
      "inset 0 0 0 0px rgba(27, 27, 29, 0), inset 0 0 0 0px rgba(58, 58, 62, 0), 0 22px 44px -18px rgba(0, 10, 60, 0.45), 0 2px 6px rgba(0, 10, 60, 0.12)",
    holeShadow:
      "inset 0 0 0 6px rgba(27, 27, 29, 1), inset 0 0 0 7px rgba(58, 58, 62, 1), 0 30px 60px -20px rgba(0, 0, 20, 0.75), 0 2px 8px rgba(0, 0, 20, 0.35)",
    ringFirst: "rgba(150, 140, 175, 0.75)",
    ring: "160 160 170",
    ringAlpha: 0.6,
    ringStep: 0.04,
    stack: "150 150 160",
    stackAlpha: 0.55,
    pill: "#ffffff",
    pillBorder: "rgba(120, 120, 130, 0.75)",
    text: "#71717a",
  },
  dark: {
    card: "#17181c",
    cardClear: "rgba(23, 24, 28, 0)",
    cardFade: "rgba(23, 24, 28, 0.7)",
    flash: "#4a4b52",
    flashDeep: "#232428",
    hole: "#000000",
    restShadow:
      "inset 0 0 0 0px rgba(40, 41, 47, 0), inset 0 0 0 0px rgba(70, 72, 82, 0), 0 22px 44px -18px rgba(0, 0, 0, 0.8), 0 0 0 1px rgba(255, 255, 255, 0.06)",
    holeShadow:
      "inset 0 0 0 6px rgba(40, 41, 47, 1), inset 0 0 0 7px rgba(70, 72, 82, 1), 0 30px 70px -18px rgba(60, 110, 255, 0.28), 0 0 0 1px rgba(255, 255, 255, 0.1)",
    ringFirst: "rgba(170, 170, 205, 0.4)",
    ring: "200 200 215",
    ringAlpha: 0.3,
    ringStep: 0.02,
    stack: "200 200 215",
    stackAlpha: 0.28,
    pill: "#1e1f24",
    pillBorder: "rgba(200, 200, 215, 0.45)",
    text: "#a1a1aa",
  },
};

export default function DynamicDropZone({
  theme = "light",
  corner = 28,
  uploadMs = 3400,
  demoFile = true,
  onDrop,
}: DynamicDropZoneProps) {
  const [phase, setPhase] = useState<Phase>("idle");
  const zone = useRef<ZoneHandle>(null);
  const fitRef = useRef<HTMLDivElement>(null);
  /* the zone is drawn at 380×280 and scaled down, as one, to fit a narrow panel */
  const [scale, setScale] = useState(1);

  useLayoutEffect(() => {
    const el = fitRef.current;
    if (!el) return;
    const fit = () => setScale(Math.min(1, el.clientWidth / W));
    fit();
    const observer = new ResizeObserver(fit);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  return (
    <div className="pdz" data-theme={theme}>
      <motion.div
        initial={{ opacity: 0, y: 16, scale: 0.98 }}
        animate={{ opacity: 1, y: 0, scale: 1 }}
        transition={{ type: "spring", visualDuration: 0.6, bounce: 0.15 }}
        className="pdz__body"
      >
        <div ref={fitRef} className="pdz__fit" style={{ height: H * scale }}>
          <div className="pdz__scaled" style={{ transform: `scale(${scale})` }}>
            <Zone ref={zone} theme={theme} corner={corner} uploadMs={uploadMs} onPhaseChange={setPhase} onDrop={onDrop} />
          </div>
        </div>

        {demoFile && (
          <div className="pdz__tray">
            <DemoFile zone={zone} available={phase === "idle"} />
          </div>
        )}
      </motion.div>
    </div>
  );
}

/* ── the zone ────────────────────────────────────────────────────────────── */

type Rect = { left: number; top: number; width: number; height: number; borderRadius: number };

/* idle: tight, evenly spaced rings framing the label */
function idleRect(i: number, radius: number): Rect {
  const inset = 7 + i * 10;
  return {
    left: inset,
    top: inset,
    width: W - inset * 2,
    height: H - inset * 2,
    borderRadius: Math.max(8, radius - 4 - i * 2.2),
  };
}

/* over: a tunnel — the rings bunch up as they fall toward the centre */
const depth = [0.14, 0.33, 0.5, 0.63, 0.73, 0.8, 0.85, 0.88];
function tunnelRect(i: number, radius: number, squeeze = 1): Rect {
  const f = depth[i];
  const w = W * (1 - f) * squeeze;
  const h = H * (1 - f) * squeeze;
  return {
    left: (W - w) / 2,
    top: (H - h) / 2,
    width: w,
    height: h,
    borderRadius: Math.max(6, (radius - 4) * (1 - f) * squeeze + 4),
  };
}

/* uploading: the innermost ring becomes the pill, the rest stack behind it
   like drawers spilling off the bottom edge */
const PILL_W = 200;
const PILL_H = 54;
function stackRect(i: number): Rect {
  const s = RINGS - 1 - i;
  const width = PILL_W + s * 20;
  return {
    left: (W - width) / 2,
    top: H / 2 - PILL_H / 2 + s * 8,
    width,
    height: s === 0 ? PILL_H : H,
    borderRadius: 13 + s,
  };
}

function cardTarget(phase: Phase, prev: Phase, p: Palette): TargetAndTransition {
  switch (phase) {
    case "over":
      /* paper → grey → ink: the zone dims into a hole as the file arrives */
      return {
        scale: 1.07,
        backgroundColor: prev === "idle" ? [p.card, p.flash, p.flashDeep, p.hole] : p.hole,
        boxShadow: p.holeShadow,
        transition: {
          ...morph,
          backgroundColor: { duration: 0.45, times: [0, 0.3, 0.62, 1], ease: "easeOut" },
          boxShadow: { duration: 0.35 },
        },
      };
    case "collapse":
      /* the hole swallows the file and pulls itself in */
      return {
        scale: 0.95,
        backgroundColor: p.hole,
        boxShadow: p.holeShadow,
        transition: { type: "spring", visualDuration: 0.34, bounce: 0 },
      };
    case "uploading":
      /* …then flashes back out to paper */
      return {
        scale: 1,
        backgroundColor: [p.hole, p.flashDeep, p.flash, p.card],
        boxShadow: p.restShadow,
        transition: {
          ...morph,
          backgroundColor: { duration: 0.6, times: [0, 0.28, 0.58, 1], ease: "easeOut" },
          boxShadow: { duration: 0.4 },
        },
      };
    default:
      return {
        scale: 1,
        backgroundColor: p.card,
        boxShadow: p.restShadow,
        transition: { ...morph, backgroundColor: { duration: 0.32 }, boxShadow: { duration: 0.32 } },
      };
  }
}

function Zone({
  ref,
  theme,
  corner,
  uploadMs,
  onPhaseChange,
  onDrop,
}: {
  ref: Ref<ZoneHandle>;
  theme: "light" | "dark";
  corner: number;
  uploadMs: number;
  onPhaseChange: (phase: Phase) => void;
  onDrop?: (files: File[]) => void;
}) {
  const [phase, setPhaseState] = useState<Phase>("idle");
  /* bumps each time the zone flips between paper and hole, so the rings can
     blink out while they rearrange */
  const [flip, setFlip] = useState(0);
  const phaseRef = useRef<Phase>("idle");
  const prevRef = useRef<Phase>("idle");
  const nativeDepth = useRef(0);
  const cardRef = useRef<HTMLDivElement>(null);
  const timers = useRef<number[]>([]);
  const radius = Math.min(40, Math.max(0, corner));
  const p = PALETTES[theme];

  const setPhase = (next: Phase) => {
    const cur = phaseRef.current;
    if (cur === next) return;
    prevRef.current = cur;
    phaseRef.current = next;
    if ((cur === "idle" && next === "over") || (cur === "over" && next === "idle")) setFlip((n) => n + 1);
    setPhaseState(next);
  };

  useEffect(() => {
    onPhaseChange(phase);
  }, [phase, onPhaseChange]);

  /* the pointer's position inside the zone, −1…1 on each axis */
  const mx = useSpring(0, { stiffness: 220, damping: 22, mass: 0.6 });
  const my = useSpring(0, { stiffness: 220, damping: 22, mass: 0.6 });

  /* a file dropped beside the zone shouldn't make the browser open it */
  useEffect(() => {
    const block = (e: globalThis.DragEvent) => {
      if (e.dataTransfer?.types.includes("Files")) e.preventDefault();
    };
    window.addEventListener("dragover", block);
    window.addEventListener("drop", block);
    const pending = timers.current;
    return () => {
      window.removeEventListener("dragover", block);
      window.removeEventListener("drop", block);
      pending.forEach(clearTimeout);
    };
  }, []);

  const inside = (x: number, y: number) => {
    const r = cardRef.current?.getBoundingClientRect();
    return !!r && x >= r.left && x <= r.right && y >= r.top && y <= r.bottom;
  };

  const track = (x: number, y: number) => {
    const r = cardRef.current?.getBoundingClientRect();
    if (!r) return;
    mx.set(Math.max(-1, Math.min(1, ((x - r.left) / r.width) * 2 - 1)));
    my.set(Math.max(-1, Math.min(1, ((y - r.top) / r.height) * 2 - 1)));
  };

  const release = () => {
    nativeDepth.current = 0;
    mx.set(0);
    my.set(0);
  };

  const accept = () => {
    release();
    timers.current.forEach(clearTimeout);
    setPhase("collapse");
    timers.current = [
      window.setTimeout(() => setPhase("uploading"), COLLAPSE_MS),
      window.setTimeout(() => setPhase("done"), COLLAPSE_MS + uploadMs),
      window.setTimeout(() => setPhase("idle"), COLLAPSE_MS + uploadMs + DONE_MS),
    ];
  };

  const open = () => phaseRef.current === "idle" || phaseRef.current === "over";

  useImperativeHandle(ref, () => ({
    dragMove(x, y) {
      if (!open()) return false;
      const hit = inside(x, y);
      if (hit) {
        track(x, y);
        setPhase("over");
      } else if (phaseRef.current === "over") {
        release();
        setPhase("idle");
      }
      return hit;
    },
    dragEnd(x, y) {
      if (phaseRef.current !== "over") return false;
      if (inside(x, y)) {
        accept();
        return true;
      }
      release();
      setPhase("idle");
      return false;
    },
    center() {
      const r = cardRef.current?.getBoundingClientRect();
      return r ? { x: r.left + r.width / 2, y: r.top + r.height / 2 } : null;
    },
  }));

  /* real files dragged in from the desktop */
  const hasFiles = (e: DragEvent) => Array.from(e.dataTransfer.types).includes("Files");
  const onDragEnter = (e: DragEvent) => {
    if (!open() || !hasFiles(e)) return;
    e.preventDefault();
    nativeDepth.current += 1;
    track(e.clientX, e.clientY);
    setPhase("over");
  };
  const onDragOver = (e: DragEvent) => {
    if (!open() || !hasFiles(e)) return;
    e.preventDefault();
    e.dataTransfer.dropEffect = "copy";
    track(e.clientX, e.clientY);
  };
  const onDragLeave = () => {
    if (phaseRef.current !== "over") return;
    nativeDepth.current -= 1;
    if (nativeDepth.current <= 0) {
      release();
      setPhase("idle");
    }
  };
  const onNativeDrop = (e: DragEvent) => {
    e.preventDefault();
    if (phaseRef.current === "over" && e.dataTransfer.files.length > 0) {
      onDrop?.(Array.from(e.dataTransfer.files));
      accept();
    }
  };

  const hole = phase === "over" || phase === "collapse";
  const busy = phase === "uploading" || phase === "done";

  return (
    <div className="pdz__zone" style={{ width: W, height: H }}>
      <motion.div
        ref={cardRef}
        role="region"
        aria-label="File drop zone"
        aria-busy={busy}
        onDragEnter={onDragEnter}
        onDragOver={onDragOver}
        onDragLeave={onDragLeave}
        onDrop={onNativeDrop}
        initial={false}
        animate={cardTarget(phase, prevRef.current, p)}
        className="pdz__card"
        style={{ borderRadius: radius }}
      >
        {/* debris being pulled into the hole */}
        <AnimatePresence>
          {hole && (
            <motion.div
              key="debris"
              className="pdz__layer"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1, transition: { duration: 0.3, delay: 0.2 } }}
              exit={{ opacity: 0, transition: quick }}
            >
              <Debris mx={mx} my={my} />
            </motion.div>
          )}
        </AnimatePresence>

        {/* the rings */}
        <div className="pdz__layer">
          {Array.from({ length: RINGS }, (_, i) => (
            <Ring key={i} index={i} phase={phase} flip={flip} radius={radius} palette={p} mx={mx} my={my} />
          ))}
        </div>

        {/* the bottom of the drawer stack fades into the card */}
        <motion.div
          className="pdz__fade"
          initial={false}
          animate={{
            opacity: busy ? 1 : 0,
            backgroundImage: `linear-gradient(to top, ${p.card}, ${p.cardFade}, ${p.cardClear})`,
          }}
          transition={{ duration: 0.3, delay: busy ? 0.25 : 0 }}
        />

        {/* labels */}
        <div className="pdz__layer pdz__labels">
          <AnimatePresence mode="popLayout" initial={false}>
            {phase === "idle" && (
              <motion.div
                key="idle"
                className="pdz__label"
                initial={{ opacity: 0, scale: 0.92, filter: "blur(4px)" }}
                animate={{
                  opacity: 1,
                  scale: 1,
                  filter: "blur(0px)",
                  color: p.text,
                  transition: { ...morph, delay: prevRef.current === "done" ? 0.3 : 0.12, color: { duration: 0.3 } },
                }}
                exit={{ opacity: 0, scale: 0.9, filter: "blur(4px)", transition: { duration: 0.12 } }}
              >
                {/* lucide: paperclip */}
                <svg className="pdz__clip" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                  <path d="m21.44 11.05-9.19 9.19a6 6 0 0 1-8.49-8.49l8.57-8.57A4 4 0 1 1 18 8.84l-8.59 8.57a2 2 0 0 1-2.83-2.83l8.49-8.48" />
                </svg>
                Drag file here
              </motion.div>
            )}

            {hole && <HoleLabel key="hole" mx={mx} my={my} sinking={phase === "collapse"} />}

            {busy && (
              <motion.div
                key="busy"
                className="pdz__label pdz__label--busy"
                initial={{ opacity: 0, filter: "blur(6px)", scale: 0.96 }}
                animate={{
                  opacity: 1,
                  filter: "blur(0px)",
                  scale: 1,
                  color: p.text,
                  transition: { duration: 0.45, delay: 0.3, ease: "easeOut", color: { duration: 0.3 } },
                }}
                exit={{ opacity: 0, filter: "blur(4px)", transition: { duration: 0.25 } }}
              >
                <span className="pdz__status">
                  <AnimatePresence initial={false}>
                    {phase === "uploading" ? (
                      <motion.span
                        key="spin"
                        className="pdz__statusIcon"
                        exit={{ scale: 0, opacity: 0, transition: { duration: 0.22, ease: "easeIn" } }}
                      >
                        <Spinner />
                      </motion.span>
                    ) : (
                      <motion.span key="check" className="pdz__statusIcon">
                        <DrawnCheck />
                      </motion.span>
                    )}
                  </AnimatePresence>
                </span>
                Uploading file(s)...
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </motion.div>

      <p className="pdz__sr" aria-live="polite">
        {phase === "over"
          ? "Release to upload"
          : phase === "uploading"
            ? "Uploading file"
            : phase === "done"
              ? "Upload complete"
              : ""}
      </p>
    </div>
  );
}

function Ring({
  index,
  phase,
  flip,
  radius,
  palette: p,
  mx,
  my,
}: {
  index: number;
  phase: Phase;
  flip: number;
  radius: number;
  palette: Palette;
  mx: MotionValue<number>;
  my: MotionValue<number>;
}) {
  /* the inner rings lean further toward the pointer — the tunnel bends */
  const lean = depth[index];
  const x = useTransform(mx, (v) => v * PULL_X * lean);
  const y = useTransform(my, (v) => v * PULL_Y * lean);
  const [scope, animateScope] = useAnimate<HTMLDivElement>();

  /* blink out while the zone swaps between paper and hole, so the rings
     rearrange unseen and fade back in already in their new shape */
  useEffect(() => {
    if (flip === 0) return;
    animateScope(scope.current, { opacity: [1, 0, 0, 1] }, { duration: 0.6, times: [0, 0.15, 0.35, 1], ease: "easeOut" });
  }, [flip, animateScope, scope]);

  const s = RINGS - 1 - index;
  const isPill = s === 0;

  let rect: Rect;
  let borderColor: string;
  let backgroundColor: string;
  if (phase === "over" || phase === "collapse") {
    rect = tunnelRect(index, radius, phase === "collapse" ? 0.82 : 1);
    borderColor = `rgba(255, 255, 255, ${Math.max(0.12, 0.85 - index * 0.11)})`;
    backgroundColor = "rgba(0, 0, 0, 0)";
  } else if (phase === "idle") {
    rect = idleRect(index, radius);
    borderColor = index === 0 ? p.ringFirst : `rgb(${p.ring} / ${p.ringAlpha - index * p.ringStep})`;
    backgroundColor = p.cardClear;
  } else {
    rect = stackRect(index);
    borderColor = isPill ? p.pillBorder : `rgb(${p.stack} / ${p.stackAlpha - s * 0.04})`;
    backgroundColor = isPill ? p.pill : p.card;
  }

  /* the rings travel one after another, so each morph reads as a ripple */
  const order = phase === "over" || phase === "collapse" ? index : s;
  const delay =
    phase === "uploading" ? 0.18 + order * 0.025 : phase === "over" ? 0.1 + order * 0.012 : 0.06 + order * 0.02;

  return (
    <motion.div
      ref={scope}
      className="pdz__ring"
      style={{ x, y, zIndex: phase === "uploading" || phase === "done" ? RINGS - s : index }}
      initial={false}
      animate={{ ...rect, borderColor, backgroundColor }}
      transition={{
        ...morph,
        delay,
        borderColor: { duration: 0.3, delay: phase === "uploading" ? 0.2 : 0 },
        backgroundColor: { duration: 0.3, delay: phase === "uploading" ? 0.2 : 0 },
      }}
    />
  );
}

function HoleLabel({ mx, my, sinking }: { mx: MotionValue<number>; my: MotionValue<number>; sinking: boolean }) {
  /* the label rides with the deepest ring */
  const x = useTransform(mx, (v) => v * PULL_X * depth[RINGS - 1]);
  const y = useTransform(my, (v) => v * PULL_Y * depth[RINGS - 1]);
  return (
    <motion.div style={{ x, y }}>
      <motion.div
        className="pdz__label pdz__label--hole"
        initial={{ opacity: 0, scale: 0.7, filter: "blur(6px)" }}
        animate={
          sinking
            ? { opacity: 0.35, scale: 0.72, filter: "blur(1px)", transition: { duration: 0.3, ease: "easeIn" } }
            : { opacity: 1, scale: 1, filter: "blur(0px)", transition: { ...morph, delay: 0.18 } }
        }
        exit={{ opacity: 0, scale: 0.6, filter: "blur(6px)", transition: { duration: 0.15 } }}
      >
        <motion.span
          className="pdz__arrow"
          animate={{ y: [0, 2.5, 0] }}
          transition={{ duration: 1.1, repeat: Infinity, ease: "easeInOut" }}
        >
          {/* lucide: circle-arrow-down */}
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={1.75} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
            <circle cx="12" cy="12" r="10" />
            <path d="M12 8v8" />
            <path d="m8 12 4 4 4-4" />
          </svg>
        </motion.span>
        Release file
      </motion.div>
    </motion.div>
  );
}

/* bits of matter spiralling in from the rim; each starts somewhere around the
   edge and shrinks to nothing at the core */
const debris = [
  { a: 200, r: 1.05, s: 20, kind: "sq", d: 3.2, delay: 0 },
  { a: 335, r: 1.0, s: 16, kind: "sq", d: 2.8, delay: 0.6 },
  { a: 95, r: 1.02, s: 7, kind: "dot", d: 2.4, delay: 0.3 },
  { a: 20, r: 1.08, s: 22, kind: "sq", d: 3.6, delay: 1.2 },
  { a: 260, r: 0.95, s: 6, kind: "dot", d: 2.2, delay: 1.5 },
  { a: 145, r: 1.1, s: 18, kind: "sq", d: 3.4, delay: 2.0 },
  { a: 300, r: 0.9, s: 8, kind: "dot", d: 2.6, delay: 0.9 },
  { a: 60, r: 1.0, s: 14, kind: "sq", d: 3.0, delay: 2.4 },
  { a: 230, r: 1.12, s: 5, kind: "dot", d: 2.0, delay: 1.8 },
  { a: 170, r: 0.92, s: 12, kind: "sq", d: 2.9, delay: 0.2 },
];

function Debris({ mx, my }: { mx: MotionValue<number>; my: MotionValue<number> }) {
  const x = useTransform(mx, (v) => v * PULL_X * 0.7);
  const y = useTransform(my, (v) => v * PULL_Y * 0.7);
  return (
    <motion.div className="pdz__core" style={{ x, y }}>
      {debris.map((d, i) => {
        const rad = (d.a * Math.PI) / 180;
        const sx = Math.cos(rad) * (W / 2) * d.r;
        const sy = Math.sin(rad) * (H / 2) * d.r;
        /* a quarter turn of swirl on the way in */
        const mid = rad + Math.PI / 4;
        const midX = Math.cos(mid) * (W / 4) * d.r;
        const midY = Math.sin(mid) * (H / 4) * d.r;
        return (
          <motion.span
            key={i}
            className={d.kind === "sq" ? "pdz__bit pdz__bit--sq" : "pdz__bit pdz__bit--dot"}
            style={{ width: d.s, height: d.s, marginLeft: -d.s / 2, marginTop: -d.s / 2 }}
            initial={{ x: sx, y: sy, opacity: 0, scale: 1 }}
            animate={{
              x: [sx, midX, 0],
              y: [sy, midY, 0],
              opacity: [0, 0.9, 0],
              scale: [1, 0.7, 0.1],
              rotate: [0, 120, 300],
            }}
            transition={{ duration: d.d, delay: d.delay, repeat: Infinity, ease: [0.55, 0, 0.85, 0.6], times: [0, 0.55, 1] }}
          />
        );
      })}
    </motion.div>
  );
}

/*
