                <rect x="13" y="24" width="100" height="72" rx="13" fill={`url(#${win})`} stroke="#ffffff" strokeOpacity="0.9" strokeWidth="1.5" />
                <g fill="none" style={{ stroke: colors[7] }} strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round">
