                  <stop offset="0.25" className="prec__rimStop prec__rimStop--1" />
                  <stop offset="1" className="prec__rimStop prec__rimStop--2" />
                </linearGradient>
              </defs>
              <path d={RIM} fill="none" stroke="url(#prec-rim)" strokeWidth="2" />
            </svg>
