  Buy: { pay: "USD", receive: "ETH", amount: "250", doing: "Buying", done: "Bought" },
  Stake: { pay: "ETH", receive: "stETH", amount: "", doing: "Staking", done: "Staked" },
};

/* entrance: each block rises out of a soft blur, one after another */
const stagger: Variants = { hidden: {}, shown: { transition: { staggerChildren: 0.07, delayChildren: 0.05 } } };
const rise: Variants = {
  hidden: { opacity: 0, y: 16, filter: "blur(6px)" },
  shown: { opacity: 1, y: 0, filter: "blur(0px)", transition: { ...morph, opacity: fade(), filter: fade() } },
};

const usd = (v: number) => "$" + v.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

function fmtOut(v: number) {
  if (v === 0) return "0";
  if (v >= 1000) return v.toLocaleString("en-US", { maximumFractionDigits: 2 });
  if (v >= 1) return v.toLocaleString("en-US", { maximumFractionDigits: 4 });
  return v.toLocaleString("en-US", { maximumSignificantDigits: 3 });
}

function fmtRate(r: number) {
  if (r >= 1000) return r.toLocaleString("en-US", { maximumFractionDigits: 2 });
  if (r >= 1) return r.toLocaleString("en-US", { maximumFractionDigits: 4 });
  return r.toLocaleString("en-US", { maximumSignificantDigits: 5 });
}

function fmtBalance(v: number) {
  if (v === 0) return "none";
  return v.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: v < 1 ? 6 : 2 });
}

/* a plain decimal string for the input: no grouping, no trailing zeros */
const toInput = (v: number) => (v > 0 ? String(Number(v.toFixed(8))) : "");

function sanitize(raw: string) {
  let s = raw.replace(",", ".").replace(/[^\d.]/g, "");
  const dot = s.indexOf(".");
  if (dot !== -1) s = s.slice(0, dot + 1) + s.slice(dot + 1).replace(/\./g, "").slice(0, 8);
  if (s.startsWith(".")) s = "0" + s;
  return s.replace(/^0+(?=\d)/, "");
}

const amountSize = (text: string) => (text.length <= 7 ? 38 : text.length <= 9 ? 32 : text.length <= 11 ? 27 : 22);

export default function SwapCard({ theme = "light", onSwap }: SwapCardProps) {
  const [mode, setMode] = useState<Mode>("Swap");
  const [pay, setPay] = useState(modes.Swap.pay);
  const [receive, setReceive] = useState(modes.Swap.receive);
  const [amount, setAmount] = useState(modes.Swap.amount);
  const [balances, setBalances] = useState(initialBalances);
  const [flips, setFlips] = useState(0);
  const [picker, setPicker] = useState<Side | null>(null);
  const [details, setDetails] = useState(false);
  const [status, setStatus] = useState<Status>("idle");
  const timers = useRef<number[]>([]);
  /* its own layout group, so two cards on a page never trade pills */
  const group = useId();
  /* flipping back and forth restores the typed amount instead of compounding rounding */
  const lastFlip = useRef<{ shown: string; typed: string } | null>(null);
  const clearTimers = () => {
    timers.current.forEach(clearTimeout);
    timers.current = [];
  };
  useEffect(() => clearTimers, []);

  const payT = bySymbol(pay);
  const receiveT = bySymbol(receive);
  const value = parseFloat(amount) || 0;
  const rate = payT.price / receiveT.price;
  const out = value * rate;
  /* the opening quote shows the reference design's figures exactly; any edit switches to live quoting */
  const preset = mode === "Swap" && pay === "USDT" && receive === "ETH" && amount === modes.Swap.amount;
  const outText = preset ? "0.0505" : fmtOut(out);
  const payUsd = preset ? 64.23 : value * payT.price;
  const receiveUsd = preset ? 64.23 : out * receiveT.price;
  const insufficient = value > balances[pay] + 1e-9;
  const ready = value > 0 && !insufficient && status === "idle";

  const label =
    status === "pending"
      ? `${modes[mode].doing}…`
      : status === "done"
        ? modes[mode].done
        : value === 0
          ? "Enter an amount"
          : insufficient
            ? `Insufficient ${pay}`
            : mode;

  const switchMode = (next: Mode) => {
    if (next === mode || status === "pending") return;
    clearTimers();
    setStatus("idle");
    setMode(next);
    setPay(modes[next].pay);
    setReceive(modes[next].receive);
    setAmount(modes[next].amount);
    setPicker(null);
  };

  const flip = () => {
    if (status === "pending") return;
    setPay(receive);
    setReceive(pay);
    const next = lastFlip.current?.shown === amount ? lastFlip.current.typed : toInput(out);
    lastFlip.current = { shown: next, typed: amount };
    setAmount(next);
    setFlips((n) => n + 1);
    setPicker(null);
  };

  const pick = (side: Side, symbol: string) => {
    setPicker(null);
    const other = side === "pay" ? receive : pay;
    if (symbol === other) return flip();
    if (side === "pay") setPay(symbol);
    else setReceive(symbol);
  };

  const submit = () => {
    if (!ready) return;
    setStatus("pending");
    timers.current.push(
      window.setTimeout(() => {
        setBalances((b) => ({ ...b, [pay]: Math.max(0, b[pay] - value), [receive]: b[receive] + out }));
        setStatus("done");
        onSwap?.({ mode, pay, receive, amount: value, received: out });
      }, 1200),
      window.setTimeout(() => setStatus("idle"), 2600),
    );
  };

  return (
    <div className="pswap" data-theme={theme}>
      <LayoutGroup id={`pswap-${group}`}>
        <motion.div variants={stagger} initial="hidden" animate="shown" className="pswap__card">
          <motion.div variants={rise} className="pswap__tabsRow">
            <Tabs mode={mode} onChange={switchMode} />
          </motion.div>

          <motion.div variants={rise} className="pswap__slot" data-raised={picker === "pay" || undefined}>
            <Panel label="Pay">
              <div className="pswap__row">
                <motion.input
                  key={`pay-${flips}-${mode}`}
                  initial={{ opacity: 0, y: 14 }}
                  animate={{ opacity: 1, y: 0, transition: { ...morph, opacity: fade() } }}
                  aria-label="Pay amount"
                  inputMode="decimal"
                  autoComplete="off"
                  placeholder="0"
                  value={amount}
                  onChange={(e) => setAmount(sanitize(e.target.value))}
                  style={{ fontSize: amountSize(amount) }}
                  className="pswap__amount pswap__input"
                />
                <TokenSelect
                  token={payT}
                  open={picker === "pay"}
                  onToggle={() => setPicker(picker === "pay" ? null : "pay")}
                  onClose={() => setPicker(null)}
                  onPick={(s) => pick("pay", s)}
                  balances={balances}
                />
              </div>
              <FooterRow
                left={<UsdValue value={payUsd} change={payT.change} />}
                right={
                  <>
                    You have <Roll className="pswap__have">{fmtBalance(balances[pay])}</Roll>
                    <motion.button
                      type="button"
                      whileHover={{ scale: 1.06 }}
                      whileTap={{ scale: 0.9 }}
                      transition={morph}
                      onClick={() => setAmount(toInput(balances[pay]))}
                      disabled={balances[pay] === 0}
                      className="pswap__max"
                    >
                      MAX
                    </motion.button>
                  </>
                }
              />
            </Panel>
          </motion.div>

          {/* the flip button sits on the seam between the two panels */}
          <div className="pswap__seam">
            <motion.button
              type="button"
              aria-label="Switch pay and receive"
              onClick={flip}
              initial={{ scale: 0.4, opacity: 0 }}
              animate={{ scale: 1, opacity: 1, transition: { ...morph, delay: 0.25 } }}
              whileHover={{ scale: 1.08 }}
              whileTap={{ scale: 0.9 }}
              className="pswap__flip"
            >
              <motion.span animate={{ rotate: flips * 180 }} transition={morph} className="pswap__flipIcon">
                {/* lucide: arrow-down-up */}
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                  <path d="m3 16 4 4 4-4" />
                  <path d="M7 20V4" />
                  <path d="m21 8-4-4-4 4" />
                  <path d="M17 4v16" />
                </svg>
              </motion.span>
            </motion.button>
          </div>

          <motion.div variants={rise} className="pswap__slot" data-raised={picker === "receive" || undefined}>
            <Panel label="Receive">
              <div className="pswap__row">
                <div
                  aria-label="Receive amount"
                  aria-live="polite"
                  style={{ fontSize: amountSize("~" + outText) }}
                  className="pswap__amount pswap__out"
                  data-empty={out === 0 || undefined}
                >
                  <span>~</span>
                  <RollingNumber value={outText} />
                </div>
                <TokenSelect
                  token={receiveT}
                  open={picker === "receive"}
                  onToggle={() => setPicker(picker === "receive" ? null : "receive")}
                  onClose={() => setPicker(null)}
                  onPick={(s) => pick("receive", s)}
                  balances={balances}
                />
              </div>
              <FooterRow
                left={<UsdValue value={receiveUsd} change={receiveT.change} />}
                right={
                  <>
                    You have <Roll className="pswap__have">{fmtBalance(balances[receive])}</Roll>
                  </>
                }
              />
            </Panel>
          </motion.div>

          <motion.div variants={rise}>
            <button type="button" aria-expanded={details} onClick={() => setDetails(!details)} className="pswap__rate">
              <span className="pswap__rateText">
                <Swap key={`${pay}-${receive}`} distance={12}>
                  {`1 ${pay} = ${fmtRate(rate)} ${receive}`}
                </Swap>
              </span>
              <motion.span animate={{ rotate: details ? 180 : 0 }} transition={morph} className="pswap__rateChevron">
                <ChevronDown />
              </motion.span>
            </button>

            <AnimatePresence initial={false}>
              {details && (
                <motion.div
                  key="details"
                  initial={{ height: 0, opacity: 0 }}
                  animate={{ height: "auto", opacity: 1, transition: { ...morph, opacity: fade(0.05) } }}
                  exit={{ height: 0, opacity: 0, transition: { ...morph, opacity: fade() } }}
                  className="pswap__drawer"
                >
                  <dl className="pswap__details">
                    {[
                      ["Price impact", `${receiveT.change.toFixed(2)}%`],
                      ["Minimum received", `${fmtOut(out * 0.995)} ${receive}`],
                      ["Slippage tolerance", "0.5%"],
                      ["Network fee", value > 0 ? "~$2.14" : "—"],
                      ["Route", `${pay} → ${receive}`],
                    ].map(([k, v], i) => (
                      <motion.div
                        key={k}
                        initial={{ opacity: 0, y: -4 }}
                        animate={{ opacity: 1, y: 0, transition: { ...morph, delay: 0.04 + i * 0.03 } }}
                        className="pswap__detail"
                      >
                        <dt>{k}</dt>
                        <dd>{v}</dd>
                      </motion.div>
                    ))}
                  </dl>
                </motion.div>
              )}
            </AnimatePresence>
          </motion.div>

          <motion.div variants={rise}>
            <LiquidButton disabled={!ready && status === "idle"} busy={status !== "idle"} success={status === "done"} onClick={submit}>
              <span className="pswap__label">
                <Swap key={label} distance={14}>
                  <span className="pswap__labelInner">
                    {status === "pending" && (
                      /* lucide: loader-circle */
                      <svg className="pswap__spin" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2.25} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                        <path d="M21 12a9 9 0 1 1-6.219-8.56" />
                      </svg>
                    )}
                    {status === "done" && <CheckIcon className="pswap__done" />}
                    {label}
                  </span>
                </Swap>
              </span>
            </LiquidButton>
          </motion.div>
        </motion.div>
      </LayoutGroup>
    </div>
  );
}

function Tabs({ mode, onChange }: { mode: Mode; onChange: (m: Mode) => void }) {
  return (
    <div role="tablist" aria-label="Action" className="pswap__tabs">
      {(Object.keys(modes) as Mode[]).map((m) => (
        <motion.button
          key={m}
          type="button"
          role="tab"
          whileTap={{ scale: 0.94 }}
          transition={morph}
          aria-selected={m === mode}
          onClick={() => onChange(m)}
          className="pswap__tab"
        >
          {m === mode && <motion.span layoutId="pswap-tab" transition={morph} className="pswap__tabPill" />}
          <span className="pswap__tabText">{m}</span>
        </motion.button>
      ))}
    </div>
  );
}

function Panel({ label, children }: { label: string; children: ReactNode }) {
  return (
    <section className="pswap__panel">
      <h2 className="pswap__panelLabel">{label}</h2>
      {children}
    </section>
  );
}

function FooterRow({ left, right }: { left: ReactNode; right: ReactNode }) {
  return (
    <div className="pswap__foot">
      <div>{left}</div>
      <div className="pswap__footRight">{right}</div>
    </div>
  );
}

function UsdValue({ value, change }: { value: number; change: number }) {
  return (
    <span className="pswap__usd">
      <RollingNumber value={usd(value)} />
      <span className="pswap__faint">
        ({change > 0 ? "+" : ""}
        {change.toFixed(2)}%)
      </span>
    </span>
  );
}

function TokenSelect({
  token,
  open,
  onToggle,
  onClose,
  onPick,
  balances,
}: {
  token: SwapCardToken;
  open: boolean;
  onToggle: () => void;
  onClose: () => void;
  onPick: (symbol: string) => void;
  balances: Record<string, number>;
}) {
  const ref = useRef<HTMLDivElement>(null);

  /* open with the current token in view, even when it sits below the fold */
  const centreCurrent = (list: HTMLUListElement | null) => {
    /* measure the <li>: its offset is relative to the list, the button's isn't mid-animation */
    const current = list?.querySelector<HTMLElement>('[aria-selected="true"]')?.closest("li");
    if (list && current) list.scrollTop = current.offsetTop - (list.clientHeight - current.offsetHeight) / 2;
  };

  /* Escape or a press anywhere else closes the list */
  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && onClose();
    const onDown = (e: PointerEvent) => !ref.current?.contains(e.target as Node) && onClose();
    window.addEventListener("keydown", onKey);
    window.addEventListener("pointerdown", onDown);
    return () => {
      window.removeEventListener("keydown", onKey);
      window.removeEventListener("pointerdown", onDown);
    };
  }, [open, onClose]);

  return (
    <div ref={ref} className="pswap__select">
      {/* a layout id per token: when the sides flip, each pill glides to the other panel */}
      <motion.button
        type="button"
        layoutId={`pswap-pill-${token.symbol}`}
        transition={morph}
        aria-haspopup="listbox"
        aria-expanded={open}
        onClick={onToggle}
        whileTap={{ scale: 0.95 }}
        className="pswap__pill"
        style={{ borderRadius: 999 }}
      >
        <motion.span layout="position" transition={morph} className="pswap__pillToken">
          <TokenIcon token={token} size={20} />
          {token.symbol}
        </motion.span>
        <motion.span layout="position" animate={{ rotate: open ? 180 : 0 }} transition={morph} className="pswap__pillChevron">
          <ChevronDown />
        </motion.span>
      </motion.button>

      <AnimatePresence>
        {open && (
          <motion.ul
            ref={centreCurrent}
            role="listbox"
            aria-label="Select token"
            initial={{ opacity: 0, scale: 0.9, y: -6, filter: "blur(4px)" }}
            animate={{ opacity: 1, scale: 1, y: 0, filter: "blur(0px)", transition: { ...morph, opacity: fade() } }}
            exit={{ opacity: 0, scale: 0.94, y: -4, filter: "blur(4px)", transition: { duration: 0.14 } }}
            style={{ originX: 1, originY: 0 }}
            className="pswap__list"
          >
            {tokens.map((t, i) => (
              <motion.li key={t.symbol} initial={{ opacity: 0, x: 8 }} animate={{ opacity: 1, x: 0, transition: { ...morph, delay: 0.03 + i * 0.025 } }}>
                <button
                  type="button"
                  role="option"
                  aria-selected={t.symbol === token.symbol}
                  onClick={() => onPick(t.symbol)}
                  className="pswap__option"
                >
                  <TokenIcon token={t} size={24} />
                  <span className="pswap__optionName">
                    <span className="pswap__optionSymbol">{t.symbol}</span>
                    <span className="pswap__optionFull">{t.name}</span>
                  </span>
                  <span className="pswap__optionBalance">{balances[t.symbol] ? fmtBalance(balances[t.symbol]) : ""}</span>
                  {t.symbol === token.symbol && <CheckIcon className="pswap__optionCheck" />}
                </button>
              </motion.li>
            ))}
          </motion.ul>
        )}
      </AnimatePresence>
    </div>
  );
}

/* text that rolls up when it changes; give it a new key to trigger the roll */
function Swap({ distance, children }: { distance: number; children: ReactNode }) {
  return (
    <motion.span
      initial={{ opacity: 0, y: distance }}
      animate={{ opacity: 1, y: 0, transition: { ...morph, opacity: fade() } }}
      className="pswap__swap"
    >
      {children}
    </motion.span>
  );
}

/* a short label that rolls whenever its text changes */
function Roll({ children, className = "" }: { children: string; className?: string }) {
  return (
    <span className={"pswap__roll " + className}>
      <Swap key={children} distance={10}>
        {children}
      </Swap>
    </span>
  );
}

/* an odometer: every character that changes slides out the top while its
   replacement rises from below; the unchanged ones stay put */
function RollingNumber({ value }: { value: string }) {
  const chars = value.split("");
  return (
    <span className="pswap__odometer">
      <AnimatePresence initial={false} mode="popLayout">
        {chars.map((c, i) => (
          <motion.span
            key={`${chars.length - i}:${c}`}
            layout="position"
            initial={{ y: "80%", opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            exit={{ y: "-80%", opacity: 0 }}
            transition={{ ...morph, opacity: fade() }}
            className="pswap__digit"
          >
            {c}
          </motion.span>
        ))}
      </AnimatePresence>
    </span>
  );
}

/* lucide: chevron-down */
function ChevronDown() {
  return (
    <svg className="pswap__chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="m6 9 6 6 6-6" />
    </svg>
  );
}

/* lucide: check */
function CheckIcon({ className }: { className: string }) {
  return (
    <svg className={className} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2.5} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="M20 6 9 17l-5-5" />
    </svg>
  );
}

/* round coin marks, drawn inline so nothing has to load */
function TokenIcon({ token, size = 22 }: { token: SwapCardToken; size?: number }) {
  return (
    <svg width={size} height={size} viewBox="0 0 32 32" aria-hidden="true" className="pswap__coin">
      <circle cx="16" cy="16" r="16" fill={token.color} />
      <Glyph symbol={token.symbol} />
    </svg>
  );
}

function Glyph({ symbol }: { symbol: string }) {
  switch (symbol) {
    case "USDT":
      return (
        <g fill="#fff">
          <path d="M8.5 8.6h15v3.3h-5.6v11.6h-3.8V11.9H8.5z" />
          <ellipse cx="16" cy="15.4" rx="7.4" ry="1.9" fill="none" stroke="#fff" strokeWidth="1.5" />
        </g>
      );
    case "ETH":
    case "stETH":
      return (
        <g fill="#fff">
          <path d="M16 5.5v7.8l6.6 2.9z" fillOpacity=".6" />
          <path d="M16 5.5 9.4 16.2l6.6-2.9z" />
          <path d="M16 21.3v5.2l6.6-9.2z" fillOpacity=".6" />
          <path d="M16 26.5v-5.2l-6.6-4z" />
          <path d="M16 20.1l6.6-3.9L16 13.3z" fillOpacity=".2" />
          <path d="M9.4 16.2l6.6 3.9v-6.8z" fillOpacity=".6" />
        </g>
      );
    case "BTC":
      return (
        <text x="16" y="22" textAnchor="middle" fontSize="17" fontWeight="700" fill="#fff" fontFamily="system-ui">
          ₿
        </text>
      );
    case "DAI":
      return (
        <text x="16" y="21.5" textAnchor="middle" fontSize="14" fontWeight="800" fill="#fff" fontFamily="system-ui">
          D
        </text>
      );
    default:
      return (
        <text x="16" y="22" textAnchor="middle" fontSize="17" fontWeight="700" fill="#fff" fontFamily="system-ui">
          $
        </text>
      );
  }
}

/* ── the liquid button ───────────────────────────────────────────────────── */

/* soft pools of light drifting across the button, like light through water */
const blobs = [
  { w: 120, h: 60, top: -16, dur: 5.5, delay: 0, color: "rgb(170 225 255 / 0.95)" },
  { w: 95, h: 50, top: 8, dur: 7, delay: -2.5, color: "rgb(125 205 255 / 0.85)" },
  { w: 135, h: 68, top: -6, dur: 8.5, delay: -5, color: "rgb(200 238 255 / 0.7)" },
];

/* tiny glints that twinkle on the surface */
const sparks = Array.from({ length: 14 }, (_, i) => ({
  left: (i * 37) % 100,
  top: 18 + ((i * 53) % 64),
  dur: 1.6 + (i % 5) * 0.35,
  delay: (i * 0.29) % 2,
}));

/* specks thrown out of the button when a swap lands */
const burst = Array.from({ length: 14 }, (_, i) => {
  const angle = (i / 14) * Math.PI * 2;
  const reach = 1 + (i % 3) * 0.22;
  return { x: Math.cos(angle) * 190 * reach, y: Math.sin(angle) * 44 * reach, size: 3 + (i % 3) };
});

type Ripple = { id: number; x: number; y: number };

/* kept light: a thin inner highlight and a short, soft drop */
const restShadow =
  "inset 0 1px 0 rgb(255 255 255 / 0.3), inset 0 -1px 2px rgb(10 40 160 / 0.2), 0 3px 8px -4px rgb(47 100 245 / 0.35)";
const hoverShadow =
  "inset 0 1px 0 rgb(255 255 255 / 0.36), inset 0 -1px 2px rgb(10 40 160 / 0.2), 0 4px 12px -5px rgb(47 100 245 / 0.45)";

function LiquidButton({
  children,
  disabled,
  busy,
  success,
  onClick,
}: {
  children: ReactNode;
  disabled: boolean;
  busy: boolean;
  success: boolean;
  onClick: () => void;
}) {
  const reduce = useReducedMotion();
  const [scope, animate] = useAnimate<HTMLDivElement>();
  const [ripples, setRipples] = useState<Ripple[]>([]);
  const [hover, setHover] = useState(false);
  const [bursts, setBursts] = useState(0);
  const nextId = useRef(0);

  /* a soft highlight that follows the pointer across the glass */
  const mx = useMotionValue(-200);
  const my = useMotionValue(-200);
  const glow = useMotionTemplate`radial-gradient(110px circle at ${mx}px ${my}px, rgb(255 255 255 / 0.28), transparent 70%)`;

  useEffect(() => {
    if (success && !reduce) setBursts((n) => n + 1);
  }, [success, reduce]);

  const interactive = !disabled && !busy;

  const onPointerDown = (e: ReactPointerEvent<HTMLButtonElement>) => {
    if (!interactive) return;
    const r = e.currentTarget.getBoundingClientRect();
    const id = nextId.current++;
    setRipples((list) => [...list, { id, x: e.clientX - r.left, y: e.clientY - r.top }]);
  };

  const onPointerMove = (e: ReactPointerEvent<HTMLButtonElement>) => {
    const r = e.currentTarget.getBoundingClientRect();
    mx.set(e.clientX - r.left);
    my.set(e.clientY - r.top);
  };

  const handleClick = () => {
    if (busy) return;
    if (disabled) {
      /* a quick "no" shake instead of a dead click */
      if (!reduce) animate(scope.current, { x: [0, -7, 7, -5, 5, -2, 0] }, { duration: 0.42, ease: "easeOut" });
      return;
    }
    onClick();
  };

  return (
    <div ref={scope} className="pswap__go">
      {/* success: a ring pulses out and specks fly from the centre */}
      {bursts > 0 && (
        <span key={bursts} aria-hidden="true" className="pswap__burst">
          <motion.span
            className="pswap__burstRing"
            initial={{ opacity: 0.7, scale: 1 }}
            animate={{ opacity: 0, scale: 1.16 }}
            transition={{ duration: 0.7, ease: "easeOut" }}
          />
          <span className="pswap__burstCore">
            {burst.map((b, i) => (
              <motion.span
                key={i}
                className="pswap__speck"
                style={{
                  width: b.size,
                  height: b.size,
                  marginLeft: -b.size / 2,
                  marginTop: -b.size / 2,
                  background: i % 2 ? "#7cc8ff" : "#4d82ff",
                }}
                initial={{ x: 0, y: 0, opacity: 1, scale: 1 }}
                animate={{ x: b.x, y: b.y, opacity: 0, scale: 0.3 }}
                transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1] }}
              />
            ))}
          </span>
        </span>
      )}

      <motion.button
        type="button"
        onClick={handleClick}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onHoverStart={() => setHover(true)}
        onHoverEnd={() => setHover(false)}
        aria-disabled={disabled || busy}
        aria-busy={busy}
        animate={{
          filter: disabled ? "saturate(0.25) brightness(1.08)" : "saturate(1) brightness(1)",
          boxShadow: hover && interactive ? hoverShadow : restShadow,
        }}
        transition={{ type: "spring", visualDuration: 0.25, bounce: 0.3 }}
        className="pswap__button"
        data-state={disabled ? "disabled" : busy ? "busy" : "ready"}
        style={{ boxShadow: restShadow }}
      >
        <span aria-hidden="true" className="pswap__water">
          {blobs.map((b, i) => (
            <motion.span
              /* re-keyed on busy so the new pace takes effect at once */
              key={`${i}-${busy}`}
              className="pswap__blob"
              style={{
                width: b.w,
                height: b.h,
                top: b.top,
                left: -b.w,
                background: `radial-gradient(closest-side, ${b.color}, transparent)`,
              }}
              animate={{ x: ["0%", "480%"] }}
              transition={{
                duration: busy ? b.dur / 3 : b.dur,
                delay: busy ? i * -0.4 : b.delay,
                repeat: Infinity,
                ease: "easeInOut",
              }}
            />
          ))}
          {sparks.map((s, i) => (
            <motion.span
              key={`s${i}`}
              className="pswap__spark"
              style={{ left: `${s.left}%`, top: `${s.top}%` }}
              animate={{ opacity: [0, 0.9, 0], scale: [0.4, 1.2, 0.4] }}
              transition={{ duration: s.dur, delay: s.delay, repeat: Infinity, ease: "easeInOut" }}
            />
          ))}
        </span>

        {/* the pointer-follow highlight */}
        <motion.span
          aria-hidden="true"
          className="pswap__glow"
          style={{ background: glow }}
          initial={false}
          animate={{ opacity: hover && interactive ? 1 : 0 }}
          transition={fade()}
        />

        {/* loading: a glossy band sweeps across while the swap is in flight */}
        <AnimatePresence>
          {busy && !success && (
            <motion.span
              key="sweep"
              aria-hidden="true"
              className="pswap__sweep"
              style={{ skewX: -12 }}
              initial={{ x: "-120%", opacity: 0 }}
              animate={{ x: "320%", opacity: 1 }}
              exit={{ opacity: 0 }}
              transition={{ x: { duration: 1, repeat: Infinity, ease: "easeInOut" }, opacity: fade() }}
            />
          )}
        </AnimatePresence>

        {/* click ripples, spreading from where the pointer landed */}
        {ripples.map((r) => (
          <motion.span
            key={r.id}
            aria-hidden="true"
            className="pswap__ripple"
            style={{ left: r.x - 10, top: r.y - 10 }}
            initial={{ scale: 0, opacity: 1 }}
            animate={{ scale: 34, opacity: 0 }}
            transition={{ duration: 0.75, ease: [0.16, 1, 0.3, 1] }}
            onAnimationComplete={() => setRipples((list) => list.filter((x) => x.id !== r.id))}
          />
        ))}

        <motion.span
          className="pswap__buttonText"
          initial={false}
          animate={{ scale: success ? [1, 1.08, 1] : 1 }}
          transition={success ? { duration: 0.45, ease: "easeOut" } : morph}
        >
          {children}
        </motion.span>
      </motion.button>
    </div>
  );
}

// Task Card — Pin UI (Component)
// npx shadcn@latest add "https://www.pinui.xyz/r/task-card.json"

"use client";

import { useCallback, useEffect, useId, useLayoutEffect, useRef, useState, type KeyboardEvent as ReactKeyboardEvent } from "react";
import { animate, AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import "./task-card.css";

/**
 * Task Card — a task with its subtasks, progress, priority, status and people.
 *
 * The subtasks hang off one connector tree: a trunk that curves into the last
 * row and a branch to every checkbox, drawn as a single SVG whose strokes are
 * snapped to whole device pixels, so at 125% or 150% display scaling no
 * segment paints heavier than another. Ticking a subtask fills its ring on a
 * spring and draws the tick; the progress pill counts up, its bar fills, and
 * its icon turns green when everything is done. Status follows along — all
 * done sets Done, reopening one puts it back In Progress.
 *
 * Priority and Status are coloured pills that open a small menu; picking an
 * option slides the label out and the next one in while the pill's width
 * follows. The ⋯ menu marks everything complete or resets the subtasks. Menus
 * take the arrow keys and Escape, and close on a press outside.
 */

type Tone = "red" | "orange" | "blue" | "gray" | "amber" | "violet" | "green";
type Option = { name: string; tone: Tone };

export type TaskCardSubtask = { label: string; done: boolean };
export type TaskCardPerson = { name: string; avatar?: string; color?: string };

export type TaskCardProps = {
  theme?: "light" | "dark";
  title?: string;
  subtasks?: TaskCardSubtask[];
  priority?: string;
  status?: string;
  people?: TaskCardPerson[];
  /** Fired whenever anything on the card changes. */
  onChange?: (state: { subtasks: TaskCardSubtask[]; priority: string; status: string }) => void;
};

const PRIORITY: Option[] = [
  { name: "Urgent", tone: "red" },
  { name: "High", tone: "orange" },
  { name: "Medium", tone: "blue" },
  { name: "Low", tone: "gray" },
];
const STATUS: Option[] = [
  { name: "To Do", tone: "gray" },
  { name: "In Progress", tone: "amber" },
  { name: "In Review", tone: "violet" },
  { name: "Done", tone: "green" },
];

const DEFAULT_SUBTASKS: TaskCardSubtask[] = [
  { label: "Design Tokens", done: true },
  { label: "Color System", done: true },
  { label: "Type System", done: true },
  { label: "Documentation", done: false },
];

const avatar = (seed: string, bg: string) =>
  `https://api.dicebear.com/9.x/avataaars/svg?seed=${encodeURIComponent(seed)}&backgroundColor=${bg}`;
const DEFAULT_PEOPLE: TaskCardPerson[] = [
  { name: "Chloe", color: "#b6e3f4", avatar: avatar("Chloe-Felix", "b6e3f4") },
  { name: "Anna", color: "#d1d4f9", avatar: avatar("Anna-Luna", "d1d4f9") },
  { name: "Ramesh", color: "#ffd5dc", avatar: avatar("Ramesh-Leo", "ffd5dc") },
];

const SPRING: Transition = { type: "spring", stiffness: 500, damping: 36 };
const SOFT: Transition = { type: "spring", stiffness: 260, damping: 30 };
const EASE_OUT = [0.22, 1, 0.36, 1] as const;

/* checkbox and row geometry, shared with the tree so each branch lands exactly on its ring */
const CHECK = { size: 18, view: 20, r: 8.9, stroke: 1.4 };
const ROW = { x: 22, pad: 2, h: 36 };
const FILL_R = 9.6;
const RING_EDGE = ROW.x + ROW.pad + CHECK.size / 2 - (CHECK.r + CHECK.stroke / 2) * (CHECK.size / CHECK.view);
/* branches end half a pixel under the ring's stroke: the ring paints on top, so the join is seamless */
const TREE = { top: 10, radius: 8, reach: RING_EDGE + 0.5 };

/* ------------------------------------------------------------------ */

function Check({ done, delay, reduced }: { done: boolean; delay: number; reduced: boolean | null }) {
  return (
    <svg viewBox={`0 0 ${CHECK.view} ${CHECK.view}`} width={CHECK.size} height={CHECK.size} className="ptask__check" aria-hidden>
      <circle className="ptask__ring" cx="10" cy="10" r={CHECK.r} fill="none" strokeWidth={CHECK.stroke} />
      <motion.circle
        className="ptask__fill"
        cx="10"
        cy="10"
        initial={{ r: 0 }}
        animate={{ r: done ? FILL_R : 0 }}
        transition={reduced ? { duration: 0 } : done ? { ...SPRING, delay } : { duration: 0.18, ease: "easeIn", delay: 0.05 }}
      />
      <motion.path
        className="ptask__tick"
        d="M6.3 10.2l2.45 2.45 5-5.1"
        fill="none"
        strokeWidth="1.9"
        strokeLinecap="round"
        strokeLinejoin="round"
        initial={{ pathLength: 0 }}
        animate={{ pathLength: done ? 1 : 0 }}
        transition={reduced ? { duration: 0 } : done ? { duration: 0.26, ease: "easeOut", delay: delay + 0.08 } : { duration: 0.12, ease: "easeIn" }}
      />
    </svg>
  );
}

/** A pill that opens a menu of options; its label slides over and its width follows. */
function PillSelect({
  label,
  value,
  options,
  open,
  onOpen,
  onClose,
  onPick,
  reduced,
}: {
  label: string;
  value: string;
  options: Option[];
  open: boolean;
  onOpen: () => void;
  onClose: (restore?: boolean) => void;
  onPick: (name: string) => void;
  reduced: boolean | null;
}) {
  const tone = options.find((o) => o.name === value)?.tone ?? "gray";
  const menuRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    if (!open) return;
    const items = Array.from(menuRef.current?.querySelectorAll<HTMLButtonElement>("[role=menuitemradio]") ?? []);
    (items.find((i) => i.getAttribute("aria-checked") === "true") ?? items[0])?.focus({ preventScroll: true });
  }, [open]);

  const onMenuKey = (e: ReactKeyboardEvent) => {
    const step = ({ ArrowDown: 1, ArrowUp: -1 } as Record<string, number>)[e.key];
    if (!step) return;
    e.preventDefault();
    const items = Array.from(menuRef.current?.querySelectorAll<HTMLButtonElement>("[role=menuitemradio]") ?? []);
    const i = items.indexOf(document.activeElement as HTMLButtonElement);
    items[(i + step + items.length) % items.length]?.focus();
  };

  return (
    <div className="ptask__dd" data-dd>
      <motion.button
        ref={triggerRef}
        type="button"
        className="ptask__pill"
        data-tone={tone}
        aria-haspopup="menu"
        aria-expanded={open}
        aria-label={`${label}: ${value}`}
        onClick={() => (open ? onClose() : onOpen())}
        layout={!reduced}
        transition={SPRING}
      >
        <span className="ptask__pillLabel">
          <AnimatePresence mode="popLayout" initial={false}>
            <motion.span
              key={value}
              initial={reduced ? false : { y: 6, opacity: 0 }}
              animate={{ y: 0, opacity: 1 }}
              exit={reduced ? { opacity: 0 } : { y: -6, opacity: 0, transition: { duration: 0.1, ease: "easeIn" } }}
              transition={SPRING}
            >
              {value}
            </motion.span>
          </AnimatePresence>
        </span>
        <motion.svg
          viewBox="0 0 24 24"
          className="ptask__chev"
          fill="none"
          stroke="currentColor"
          strokeWidth="2.4"
          strokeLinecap="round"
          strokeLinejoin="round"
          aria-hidden
          layout={!reduced ? "position" : false}
          animate={{ rotate: open ? 180 : 0 }}
          transition={SPRING}
        >
          <path d="m6 9 6 6 6-6" />
        </motion.svg>
      </motion.button>

      <AnimatePresence>
        {open && (
          <motion.div
            ref={menuRef}
            className="ptask__menu"
            role="menu"
            aria-label={label}
            onKeyDown={onMenuKey}
            initial={reduced ? { opacity: 0 } : { opacity: 0, scale: 0.96, y: -4 }}
            animate={{ opacity: 1, scale: 1, y: 0, transition: { ...SPRING, opacity: { duration: 0.14, ease: "easeOut" } } }}
            exit={reduced ? { opacity: 0 } : { opacity: 0, scale: 0.98, y: -2, transition: { duration: 0.1, ease: "easeIn" } }}
          >
            {options.map((o) => (
              <button
                key={o.name}
                type="button"
                role="menuitemradio"
                aria-checked={o.name === value}
                className="ptask__item"
                data-tone={o.tone}
                onClick={() => {
                  onPick(o.name);
                  onClose(true);
                  triggerRef.current?.focus({ preventScroll: true });
                }}
              >
                <span className="ptask__dot" />
                <span className="ptask__itemName">{o.name}</span>
                <svg viewBox="0 0 24 24" className="ptask__tickmark" data-on={o.name === value || undefined} fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
                  <path d="m5 12.5 4.5 4.5L19 7.5" />
                </svg>
              </button>
            ))}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

/* ------------------------------------------------------------------ */

export default function TaskCard({
  theme = "light",
  title = "Design System",
  subtasks = DEFAULT_SUBTASKS,
  priority: initialPriority = "Urgent",
  status: initialStatus = "In Progress",
  people = DEFAULT_PEOPLE,
  onChange,
}: TaskCardProps) {
  const reduced = useReducedMotion();
  const uid = useId();
  const [tasks, setTasks] = useState(() => subtasks.map((t) => ({ ...t })));
  const [priority, setPriority] = useState(initialPriority);
  const [status, setStatus] = useState(initialStatus);
  const [openKey, setOpenKey] = useState<"more" | "priority" | "status" | null>(null);
  const [failed, setFailed] = useState<Set<number>>(() => new Set());
  /* the counters write their digits straight to the DOM: a count-up never re-renders the card */
  const shownRef = useRef({ done: 0, pct: 0 });
  const doneRef = useRef<HTMLSpanElement>(null);
  const pctRef = useRef<HTMLSpanElement>(null);
  const first = useRef(true);
  const rootRef = useRef<HTMLDivElement>(null);
  const treeRef = useRef<SVGSVGElement>(null);
  const moreRef = useRef<HTMLButtonElement>(null);
  const moreMenuRef = useRef<HTMLDivElement>(null);
  const [tree, setTree] = useState<{ trunk: string; branches: string[]; w: number } | null>(null);
  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;

  const total = tasks.length;
  const done = tasks.filter((t) => t.done).length;
  const pct = total ? Math.round((done / total) * 100) : 0;
  const allDone = total > 0 && done === total;

  /* the counters roll to their new values */
  useEffect(() => {
    const delay = first.current ? 0.25 : 0;
    first.current = false;
    const opts = { duration: reduced ? 0 : 0.45, delay: reduced ? 0 : delay, ease: EASE_OUT };
    const write = (el: HTMLSpanElement | null, v: number) => {
      const t = String(Math.round(v));
      if (el && el.textContent !== t) el.textContent = t;
    };
    const a = animate(shownRef.current.done, done, {
      ...opts,
      onUpdate: (v) => write(doneRef.current, (shownRef.current.done = v)),
    });
    const b = animate(shownRef.current.pct, pct, {
      ...opts,
      onUpdate: (v) => write(pctRef.current, (shownRef.current.pct = v)),
    });
    return () => {
      a.stop();
      b.stop();
    };
  }, [done, pct, reduced]);

  useEffect(() => {
    onChangeRef.current?.({ subtasks: tasks, priority, status });
  }, [tasks, priority, status]);

  /* status follows completion: all done → Done, reopened → back to In Progress */
  const commitTasks = useCallback(
    (next: TaskCardSubtask[]) => {
      setTasks(next);
      const all = next.every((t) => t.done);
      if (all) setStatus("Done");
      else setStatus((s) => (s === "Done" ? "In Progress" : s));
    },
    [],
  );

  /* the tree, snapped to whole device pixels so every segment draws at the same weight.
     Its shape depends only on how many rows there are, so ticking a box never re-lays it */
  const rows = tasks.length;
  const layoutTree = useCallback(() => {
    const svg = treeRef.current;
    if (!svg) return;
    const dpr = window.devicePixelRatio || 1;
    const k = Math.max(1, Math.round(dpr));
    const w = k / dpr;
    const o = svg.getBoundingClientRect();
    const crisp = (pos: number, origin: number) => (Math.round((origin + pos) * dpr - k / 2) + k / 2) / dpr - origin;
    const x = crisp(0.5, o.left);
    const ys = Array.from({ length: rows }, (_, i) => crisp(TREE.top + ROW.h * i + ROW.h / 2, o.top));
    const yl = ys[ys.length - 1] ?? 0;
    const r = TREE.radius;
    const next = {
      trunk: `M${x} 0V${yl - r}A${r} ${r} 0 0 0 ${x + r} ${yl}H${TREE.reach}`,
      branches: ys.slice(0, -1).map((y) => `M${x} ${y}H${TREE.reach}`),
      w,
    };
    /* only commit when a path actually moved */
    setTree((prev) =>
      prev && prev.w === next.w && prev.trunk === next.trunk && prev.branches.join() === next.branches.join() ? prev : next,
    );
  }, [rows]);

  useLayoutEffect(() => {
    layoutTree();
    let frame = 0;
    const ro = new ResizeObserver(() => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(layoutTree);
    });
    if (rootRef.current) ro.observe(rootRef.current);
    addEventListener("resize", layoutTree);
    document.fonts?.ready.then(() => layoutTree());
    let mq: MediaQueryList | null = null;
    const watch = () => {
      mq = matchMedia(`(resolution: ${window.devicePixelRatio}dppx)`);
      mq.addEventListener("change", onScale, { once: true });
    };
    const onScale = () => {
      layoutTree();
      watch();
    };
    watch();
    /* the card slides in; place the tree again where it lands */
    const t = setTimeout(layoutTree, 700);
    return () => {
      ro.disconnect();
      cancelAnimationFrame(frame);
      removeEventListener("resize", layoutTree);
      mq?.removeEventListener("change", onScale);
      clearTimeout(t);
    };
  }, [layoutTree]);

  /* menus close on a press outside or Escape */
  useEffect(() => {
    if (!openKey) return;
    const away = (e: PointerEvent) => {
      const t = e.target as Element;
      if (!rootRef.current?.contains(t) || !t.closest?.("[data-dd]")) setOpenKey(null);
    };
    const esc = (e: KeyboardEvent) => {
      if (e.key !== "Escape") return;
      setOpenKey(null);
      if (openKey === "more") moreRef.current?.focus({ preventScroll: true });
    };
    document.addEventListener("pointerdown", away);
    document.addEventListener("keydown", esc);
    return () => {
      document.removeEventListener("pointerdown", away);
      document.removeEventListener("keydown", esc);
    };
  }, [openKey]);

  useEffect(() => {
    if (openKey === "more") moreMenuRef.current?.querySelector<HTMLButtonElement>("button")?.focus({ preventScroll: true });
  }, [openKey]);

  const enter = (i: number) => ({
    initial: reduced ? false : ({ opacity: 0, y: 5 } as const),
    animate: { opacity: 1, y: 0 },
    transition: { ...SOFT, opacity: { duration: 0.35, ease: EASE_OUT, delay: 0.08 + i * 0.035 }, delay: 0.08 + i * 0.035 },
  });

  const moreKey = (e: ReactKeyboardEvent) => {
    const step = ({ ArrowDown: 1, ArrowUp: -1 } as Record<string, number>)[e.key];
    if (!step) return;
    e.preventDefault();
    const items = Array.from(moreMenuRef.current?.querySelectorAll<HTMLButtonElement>("button") ?? []);
    const i = items.indexOf(document.activeElement as HTMLButtonElement);
    items[(i + step + items.length) % items.length]?.focus();
  };

  return (
    <div ref={rootRef} className="ptask" data-theme={theme}>
      <motion.section
        className="ptask__card"
        aria-label={title}
        initial={reduced ? false : { opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ ...SOFT, opacity: { duration: 0.35, ease: EASE_OUT } }}
      >
        {/* header */}
        <motion.header className="ptask__head" {...enter(0)}>
          <div className="ptask__brand">
            <span className="ptask__logo" aria-hidden>
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinejoin="round">
                <path d="M12 2.6l8.15 4.7v9.4L12 21.4l-8.15-4.7V7.3z" />
                <circle cx="12" cy="12" r="3.4" />
              </svg>
            </span>
            <h3 className="ptask__title">{title}</h3>
          </div>

          <div className="ptask__dd" data-dd>
            <button
              ref={moreRef}
              type="button"
              className="ptask__icon"
              aria-haspopup="menu"
              aria-expanded={openKey === "more"}
              aria-label="More options"
              onClick={() => setOpenKey((k) => (k === "more" ? null : "more"))}
            >
              <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden>
                <circle cx="5" cy="12" r="1.8" />
                <circle cx="12" cy="12" r="1.8" />
                <circle cx="19" cy="12" r="1.8" />
              </svg>
            </button>
            <AnimatePresence>
              {openKey === "more" && (
                <motion.div
                  ref={moreMenuRef}
                  className="ptask__menu ptask__menu--right"
                  role="menu"
                  aria-label="More options"
                  onKeyDown={moreKey}
                  initial={reduced ? { opacity: 0 } : { opacity: 0, scale: 0.96, y: -4 }}
                  animate={{ opacity: 1, scale: 1, y: 0, transition: { ...SPRING, opacity: { duration: 0.14, ease: "easeOut" } } }}
                  exit={reduced ? { opacity: 0 } : { opacity: 0, scale: 0.98, y: -2, transition: { duration: 0.1, ease: "easeIn" } }}
                >
                  <button
                    type="button"
                    role="menuitem"
                    className="ptask__item"
                    onClick={() => {
                      commitTasks(tasks.map((t) => ({ ...t, done: true })));
                      setOpenKey(null);
                      moreRef.current?.focus({ preventScroll: true });
                    }}
                  >
                    <svg viewBox="0 0 24 24" className="ptask__itemIcon" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
                      <circle cx="12" cy="12" r="9" />
                      <path d="m8.5 12.5 2.5 2.5 4.5-5" />
                    </svg>
                    Mark all complete
                  </button>
                  <button
                    type="button"
                    role="menuitem"
                    className="ptask__item"
                    onClick={() => {
                      commitTasks(subtasks.map((t) => ({ ...t })));
                      setOpenKey(null);
                      moreRef.current?.focus({ preventScroll: true });
                    }}
                  >
                    <svg viewBox="0 0 24 24" className="ptask__itemIcon" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
                      <path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8" />
                      <path d="M3 3v5h5" />
                    </svg>
                    Reset subtasks
                  </button>
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        </motion.header>

        {/* progress */}
        <motion.div className="ptask__progressRow" {...enter(1)}>
          <div
            className="ptask__progress"
            role="progressbar"
            aria-label="Subtask progress"
            aria-valuemin={0}
            aria-valuemax={100}
            aria-valuenow={pct}
          >
            <svg viewBox="0 0 24 24" className="ptask__progressIcon" data-done={allDone || undefined} fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
