                animate={{ width: `${pct}%` }}
                transition={reduced ? { duration: 0 } : { ...SOFT, delay: first.current ? 0.25 : 0 }}
              />
            </span>
            <span className="ptask__pct">
              <span ref={pctRef}>0</span>%
