              <>
                <motion.path
                  className="ptask__line"
                  d={tree.trunk}
                  strokeWidth={tree.w}
                  initial={reduced ? false : { pathLength: 0 }}
                  animate={{ pathLength: 1 }}
                  transition={{ duration: 0.5, ease: EASE_OUT, delay: 0.14 }}
                />
                {tree.branches.map((d, i) => (
                  <motion.path
