                  />
                ))}
              </>
            )}
          </svg>
          {tasks.map((t, i) => (
            <li key={`${uid}-${i}`} className="ptask__task">
              <motion.button
                type="button"
                role="checkbox"
                aria-checked={t.done}
                className="ptask__row"
