// Contact Form — Pin UI (Blocx)
// npx shadcn@latest add "https://www.pinui.xyz/r/blocx/contact-form.json"
// 上游为 Next.js 区块：next/font 已换成本地字体栈，静态资源放在 public/blocx/ 下。

"use client";

import { useState, type FormEvent } from "react";
import { animate, AnimatePresence, motion, MotionConfig, type Variants } from "motion/react";
import { Inter_Tight } from "next/font/google";
import "./contact-form.css";

/**
 * Contact Form — "Wanna Work With Me…", a black-and-white contact block.
 *
 * From the Figma frame (Contact): a light page ruled with dashed guides, a
 * headline, and two black columns — a greyscale hand reaching in on the left,
 * and the form on the right: Email, Contact and Message as black tiles with
 * white-outlined fields, then a Contact Me tile marked at its corners.
 *
 * On arrival the guides draw themselves across the page and their pins pop
 * in, the headline rises a word at a time, the photo is revealed upward as
 * the hand settles, and the tiles follow on a stagger. The fields brighten
 * on focus and shake when they are wrong. The button fills white from the
 * bottom as its label rolls over, its corner marks spread, it shows that it
 * is sending, and it turns to a drawn check once the message lands. Wire
 * `onSubmit` to your own endpoint; the demo just waits a moment.
 *
 * The frame is drawn in its own units scaled to fit the window — width and
 * height — so the whole block always sits in one viewport; a portrait tablet
 * gets a tighter frame, and a phone stacks and scrolls.
 */

const interTight = Inter_Tight({ subsets: ["latin"], weight: "400", variable: "--cf-font", display: "swap" });

const HAND = "/blocx/contact-form/hand.webp";
const EASE_OUT = [0.16, 1, 0.3, 1] as const;
const TITLE = "Wanna Work With Me...";

export type ContactValues = { email: string; contact: string; message: string };

type Field = {
  name: keyof ContactValues;
  label: string;
  placeholder: string;
  type: string;
  autoComplete: string;
  inputMode?: "email" | "tel" | "text";
};

const FIELDS: Field[] = [
  { name: "email", label: "Email", placeholder: "Enter Your Email...", type: "email", autoComplete: "email", inputMode: "email" },
  { name: "contact", label: "Contact", placeholder: "Enter Your Contact...", type: "tel", autoComplete: "tel", inputMode: "tel" },
  { name: "message", label: "Message", placeholder: "Enter Your Message...", type: "text", autoComplete: "off" },
];

const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function validate(v: ContactValues): Partial<Record<keyof ContactValues, string>> {
  const errors: Partial<Record<keyof ContactValues, string>> = {};
  if (!EMAIL.test(v.email.trim())) errors.email = "Enter a valid email";
  if (v.contact.trim() && !/^[+\d][\d\s().-]{5,}$/.test(v.contact.trim())) errors.contact = "Enter a valid number";
  if (v.message.trim().length < 2) errors.message = "Tell me a little about it";
  return errors;
}

const rise: Variants = {
  hidden: { opacity: 0, y: 28, filter: "blur(8px)" },
  show: (delay: number) => ({
    opacity: 1,
    y: 0,
    filter: "blur(0px)",
    transition: { duration: 0.9, ease: EASE_OUT, delay },
  }),
};

type Status = "idle" | "sending" | "sent";

export default function ContactForm({
  onSubmit,
}: {
  /** Send the message wherever it needs to go. Left out, the demo waits a moment and says thanks. */
  onSubmit?: (values: ContactValues) => Promise<void> | void;
}) {
  const [values, setValues] = useState<ContactValues>({ email: "", contact: "", message: "" });
  const [errors, setErrors] = useState<Partial<Record<keyof ContactValues, string>>>({});
  const [status, setStatus] = useState<Status>("idle");

  async function handleSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (status !== "idle") return;
    const found = validate(values);
    setErrors(found);
    const wrong = FIELDS.filter((f) => found[f.name]);
    if (wrong.length) {
      // every wrong tile gives a short shake; focus lands on the first
      for (const f of wrong) {
        const tile = document.getElementById(`cf-tile-${f.name}`);
        if (tile) animate(tile, { x: [0, -8, 7, -5, 3, 0] }, { duration: 0.45, ease: "easeOut" });
      }
      document.getElementById(`cf-${wrong[0].name}`)?.focus();
      return;
    }
    setStatus("sending");
    try {
      await (onSubmit ? onSubmit(values) : new Promise((r) => setTimeout(r, 1300)));
      setStatus("sent");
      setValues({ email: "", contact: "", message: "" });
      setTimeout(() => setStatus("idle"), 3200);
    } catch {
      setStatus("idle");
    }
  }

  return (
    <MotionConfig reducedMotion="user">
      <main className={`cf-page ${interTight.variable}`}>
        <section className="cf" aria-labelledby="cf-title">
          {/* the guides draw themselves across the page, edge to edge */}
          <motion.span
            className="cf__rail cf__rail--h"
            aria-hidden
            initial={{ scaleX: 0 }}
            animate={{ scaleX: 1 }}
            transition={{ duration: 1.4, ease: EASE_OUT }}
          />
          <motion.span
            className="cf__rail cf__rail--l"
            aria-hidden
            initial={{ scaleY: 0 }}
            animate={{ scaleY: 1 }}
            transition={{ duration: 1.4, ease: EASE_OUT, delay: 0.1 }}
          />
          <motion.span
            className="cf__rail cf__rail--r"
            aria-hidden
            initial={{ scaleY: 0 }}
            animate={{ scaleY: 1 }}
            transition={{ duration: 1.4, ease: EASE_OUT, delay: 0.1 }}
          />

          {/* the raised pins where the guides cross */}
          {(["l", "r"] as const).map((side, i) => (
            <motion.span
              key={side}
              className={`cf__pin cf__pin--${side}`}
              aria-hidden
              initial={{ scale: 0, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              transition={{ type: "spring", stiffness: 420, damping: 18, delay: 0.7 + i * 0.08 }}
            />
          ))}

          <div className="cf__stage">
            <h2 id="cf-title" className="cf__title" aria-label={TITLE}>
              {TITLE.split(" ").map((word, i) => (
                <span key={i} className="cf__word-mask" aria-hidden>
                  <motion.span
                    className="cf__word"
                    initial={{ y: "105%", filter: "blur(6px)" }}
                    animate={{ y: 0, filter: "blur(0px)" }}
                    transition={{ duration: 0.9, ease: EASE_OUT, delay: 0.2 + i * 0.07 }}
                  >
                    {word}
                  </motion.span>
                </span>
              ))}
            </h2>

            <div className="cf__row">
              <motion.figure
                className="cf__photo"
                initial={{ clipPath: "inset(100% 0% 0% 0%)" }}
                animate={{ clipPath: "inset(0% 0% 0% 0%)" }}
                transition={{ duration: 1.2, ease: EASE_OUT, delay: 0.35 }}
              >
                <motion.div
                  className="cf__hand"
                  initial={{ scale: 1.12, x: "-56%", y: "-46%" }}
                  animate={{ scale: 1, x: "-50%", y: "-50%" }}
                  transition={{ duration: 1.8, ease: EASE_OUT, delay: 0.35 }}
                >
                  <div className="cf__hand-crop">
                    <img src={HAND} alt="" width={1536} height={1024} draggable={false} />
                  </div>
                </motion.div>
              </motion.figure>

              <form className="cf__form" onSubmit={handleSubmit} noValidate aria-describedby="cf-status">
                {FIELDS.map((f, i) => (
                  <motion.div
                    key={f.name}
                    id={`cf-tile-${f.name}`}
                    className={`cf__tile${errors[f.name] ? " is-invalid" : ""}`}
                    variants={rise}
                    initial="hidden"
                    animate="show"
                    custom={0.5 + i * 0.09}
                  >
                    <label className="cf__label" htmlFor={`cf-${f.name}`}>
                      {f.label}
                    </label>
                    <input
                      id={`cf-${f.name}`}
                      className="cf__input"
                      name={f.name}
                      type={f.type}
                      inputMode={f.inputMode}
                      autoComplete={f.autoComplete}
                      placeholder={f.placeholder}
                      value={values[f.name]}
                      required={f.name !== "contact"}
                      aria-invalid={Boolean(errors[f.name])}
                      aria-describedby={errors[f.name] ? `cf-${f.name}-error` : undefined}
                      onChange={(e) => {
                        const v = e.target.value;
                        setValues((prev) => ({ ...prev, [f.name]: v }));
                        if (errors[f.name]) setErrors((prev) => ({ ...prev, [f.name]: undefined }));
                      }}
                    />
                    <AnimatePresence>
                      {errors[f.name] && (
                        <motion.span
                          id={`cf-${f.name}-error`}
                          className="cf__error"
                          initial={{ opacity: 0, x: 8 }}
                          animate={{ opacity: 1, x: 0 }}
                          exit={{ opacity: 0, x: 8 }}
                          transition={{ duration: 0.25, ease: EASE_OUT }}
                        >
                          {errors[f.name]}
                        </motion.span>
                      )}
                    </AnimatePresence>
                  </motion.div>
                ))}

                <motion.button
                  type="submit"
                  className={`cf__submit is-${status}`}
                  variants={rise}
                  initial="hidden"
                  animate="show"
                  custom={0.77}
                  whileTap={status === "idle" ? { scale: 0.985 } : undefined}
                  aria-disabled={status !== "idle"}
                  aria-busy={status === "sending"}
                >
                  <span className="cf__fill" aria-hidden />
                  {/* the corner marks spread on hover */}
                  <span className="cf__corner cf__corner--tl" aria-hidden />
                  <span className="cf__corner cf__corner--tr" aria-hidden />
                  <span className="cf__corner cf__corner--bl" aria-hidden />
                  <span className="cf__corner cf__corner--br" aria-hidden />

                  <AnimatePresence mode="popLayout" initial={false}>
                    <motion.span
                      key={status}
                      className="cf__submit-face"
                      initial={{ opacity: 0, y: "70%", filter: "blur(6px)" }}
                      animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
                      exit={{ opacity: 0, y: "-70%", filter: "blur(6px)" }}
                      transition={{ duration: 0.45, ease: EASE_OUT }}
                    >
                      {status === "idle" && (
                        <span className="cf__roll">
                          <span className="cf__roll-line">Contact Me</span>
                          <span className="cf__roll-line" aria-hidden>
                            Contact Me
                            <svg className="cf__arrow" viewBox="0 0 24 24" aria-hidden>
                              <path d="M5 12h14m-6-6 6 6-6 6" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" />
                            </svg>
                          </span>
                        </span>
                      )}
                      {status === "sending" && (
                        <span className="cf__sending">
                          Sending
                          <span className="cf__dots" aria-hidden>
                            {[0, 1, 2].map((d) => (
                              <motion.span
                                key={d}
                                animate={{ y: [0, -6, 0], opacity: [0.4, 1, 0.4] }}
                                transition={{ duration: 0.8, repeat: Infinity, ease: "easeInOut", delay: d * 0.14 }}
                              />
                            ))}
                          </span>
                        </span>
                      )}
                      {status === "sent" && (
                        <span className="cf__sent">
                          <svg className="cf__check" viewBox="0 0 24 24" aria-hidden>
                            <motion.path
                              d="m5 12.5 4.5 4.5L19 7.5"
                              fill="none"
                              stroke="currentColor"
                              strokeWidth="1.8"
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              initial={{ pathLength: 0 }}
                              animate={{ pathLength: 1 }}
                              transition={{ duration: 0.5, ease: EASE_OUT, delay: 0.15 }}
                            />
                          </svg>
                          Thank You
                        </span>
                      )}
                    </motion.span>
                  </AnimatePresence>
                </motion.button>
                <p id="cf-status" className="cf__sr" role="status" aria-live="polite">
                  {status === "sending" ? "Sending your message…" : status === "sent" ? "Message sent. Thank you!" : ""}
                </p>
              </form>
            </div>
          </div>
        </section>
      </main>
    </MotionConfig>
  );
}

// Halo Sign In — Pin UI (Blocx)
// npx shadcn@latest add "https://www.pinui.xyz/r/blocx/halo-sign-in.json"
// 上游为 Next.js 区块：next/font 已换成本地字体栈，静态资源放在 public/blocx/ 下。

"use client";

import { useId, useState, type FormEvent, type InputHTMLAttributes, type ReactNode, type SVGProps } from "react";
import { AnimatePresence, motion, MotionConfig, type Transition, type Variants } from "motion/react";
import { Inter } from "next/font/google";
import "./halo-sign-in.css";

/**
 * Halo Sign In — a soft, two-layer sign-in card for a rental app.
 *
 * A white card sits in a pale tray: an app mark in a slowly turning field of
 * dots, a title, email and password fields with a show / hide toggle, a black
 * Sign In button, and Google, Facebook and Apple underneath a dashed rule; the
 * tray's lip holds the sign-up link.
 *
 * On arrival the tray rises, the dot field unwinds into place, the mark
 * springs in and draws its house outline, and each row rises and un-blurs on a
 * stagger. The fields brighten on focus. The button rolls its label to
 * "Signing in…" with a spinner and then "Welcome back". Wire `onSubmit` to
 * your own auth; the demo waits a moment.
 */

const inter = Inter({ subsets: ["latin"], variable: "--hsi-font", display: "swap" });

const EASE_OUT = [0.16, 1, 0.3, 1] as const;
const SPRING: Transition = { type: "spring", stiffness: 260, damping: 26, mass: 0.9 };

const stagger = (delayChildren: number, staggerChildren: number): Variants => ({
  hidden: {},
  show: { transition: { delayChildren, staggerChildren } },
});

/* rise and un-blur: the entrance for every row */
const item: Variants = {
  hidden: { opacity: 0, y: 14, filter: "blur(6px)" },
  show: { opacity: 1, y: 0, filter: "blur(0px)", transition: { duration: 0.7, ease: EASE_OUT } },
};

export type HaloSignInValues = { email: string; password: string };

type Status = "idle" | "loading" | "done";

export default function HaloSignIn({
  onSubmit,
  onProvider,
}: {
  /** Sign the visitor in. Left out, the demo waits a moment and says welcome back. */
  onSubmit?: (values: HaloSignInValues) => Promise<void> | void;
  /** Called when one of the social buttons is pressed. */
  onProvider?: (provider: "google" | "facebook" | "apple") => void;
}) {
  const [showPassword, setShowPassword] = useState(false);
  const [status, setStatus] = useState<Status>("idle");

  async function handleSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (status !== "idle") return;
    const data = new FormData(e.currentTarget);
    setStatus("loading");
    try {
      await (onSubmit
        ? onSubmit({ email: String(data.get("email") ?? ""), password: String(data.get("password") ?? "") })
        : new Promise((r) => setTimeout(r, 1100)));
      setStatus("done");
      setTimeout(() => setStatus("idle"), 1500);
    } catch {
      setStatus("idle");
    }
  }

  return (
    <MotionConfig reducedMotion="user">
      <main className={`hsi ${inter.variable}`}>
        <motion.section
          aria-labelledby="hsi-title"
          initial={{ opacity: 0, y: 24, scale: 0.97 }}
          animate={{ opacity: 1, y: 0, scale: 1 }}
          transition={{ duration: 0.9, ease: EASE_OUT }}
          className="hsi__tray"
        >
          <motion.div variants={stagger(0.25, 0.055)} initial="hidden" animate="show" className="hsi__card">
            <Halo />

            <motion.header variants={item} className="hsi__head">
              <h1 id="hsi-title" className="hsi__title">
                Sign in to continue
              </h1>
              <p className="hsi__lede">Please sign in to start your rental application</p>
            </motion.header>

            <form onSubmit={handleSubmit} className="hsi__form">
              <motion.div variants={item}>
                <Field type="email" name="email" label="Email" autoComplete="email" icon={<MailIcon />} />
              </motion.div>

              <motion.div variants={item}>
                <Field
                  type={showPassword ? "text" : "password"}
                  name="password"
                  label="Password"
                  autoComplete="current-password"
                  minLength={6}
                  icon={<LockIcon />}
                  trailing={
                    <button
                      type="button"
                      onClick={() => setShowPassword((v) => !v)}
                      aria-label={showPassword ? "Hide password" : "Show password"}
                      aria-pressed={showPassword}
                      className="hsi__peek"
                    >
                      <AnimatePresence mode="popLayout" initial={false}>
                        <motion.span
                          key={showPassword ? "off" : "on"}
                          initial={{ opacity: 0, scale: 0.6, rotate: -20 }}
                          animate={{ opacity: 1, scale: 1, rotate: 0 }}
                          exit={{ opacity: 0, scale: 0.6, rotate: 20 }}
                          transition={{ duration: 0.2 }}
                          className="hsi__peek-icon"
                        >
                          {showPassword ? <EyeOffIcon /> : <EyeIcon />}
                        </motion.span>
                      </AnimatePresence>
                    </button>
                  }
                />
              </motion.div>

              <motion.div variants={item} className="hsi__submit-row">
                <motion.button
                  type="submit"
                  whileHover={{ y: -1 }}
                  whileTap={{ scale: 0.985, y: 0 }}
                  transition={SPRING}
                  disabled={status !== "idle"}
                  aria-live="polite"
                  className="hsi__submit"
                >
                  <AnimatePresence mode="popLayout" initial={false}>
                    <motion.span
                      key={status}
                      initial={{ opacity: 0, y: 12 }}
                      animate={{ opacity: 1, y: 0 }}
                      exit={{ opacity: 0, y: -12 }}
                      transition={{ duration: 0.25, ease: EASE_OUT }}
                      className="hsi__submit-label"
                    >
                      {status === "idle" && "Sign In"}
                      {status === "loading" && (
                        <>
                          <Spinner /> Signing in…
                        </>
                      )}
                      {status === "done" && "Welcome back"}
                    </motion.span>
                  </AnimatePresence>
                </motion.button>
              </motion.div>
            </form>

            <motion.div variants={item} className="hsi__or">
              <span className="hsi__rule" aria-hidden />
              <span>Or continue with</span>
              <span className="hsi__rule" aria-hidden />
            </motion.div>

            <motion.div variants={item} className="hsi__socials">
              <SocialButton label="Continue with Google" onClick={() => onProvider?.("google")}>
                <GoogleIcon />
              </SocialButton>
              <SocialButton label="Continue with Facebook" onClick={() => onProvider?.("facebook")}>
                <FacebookIcon />
              </SocialButton>
              <SocialButton label="Continue with Apple" onClick={() => onProvider?.("apple")}>
                <AppleIcon />
              </SocialButton>
            </motion.div>
          </motion.div>

          <motion.p
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.85, duration: 0.6 }}
            className="hsi__foot"
          >
            Don&apos;t have an account?{" "}
            <a href="#signup" className="hsi__link">
              Sign Up
            </a>
          </motion.p>
        </motion.section>
      </main>
    </MotionConfig>
  );
}

/* the app mark in a slowly turning field of dots that fades at the edges */
function Halo() {
  const rings = [
    { r: 34, n: 18 },
    { r: 44, n: 24 },
    { r: 54, n: 30 },
  ];
  return (
    <div className="hsi__halo">
      <motion.svg
        viewBox="-60 -60 120 120"
        className="hsi__dots"
        initial={{ opacity: 0, scale: 0.8, rotate: -30 }}
        animate={{ opacity: 1, scale: 1, rotate: 0 }}
        transition={{ duration: 1.4, ease: EASE_OUT, delay: 0.15 }}
        aria-hidden
      >
        <motion.g animate={{ rotate: 360 }} transition={{ duration: 90, ease: "linear", repeat: Infinity }}>
          {rings.flatMap(({ r, n }, ri) =>
            Array.from({ length: n }, (_, i) => {
              const a = (i / n) * Math.PI * 2 + ri * 0.35;
              /* rounded, so the server's trig and the browser's agree to the last digit and hydration matches */
              const cx = Math.round(Math.cos(a) * r * 1000) / 1000;
              const cy = Math.round(Math.sin(a) * r * 1000) / 1000;
              return <circle key={`${ri}-${i}`} cx={cx} cy={cy} r={0.9} fill="currentColor" />;
            }),
          )}
        </motion.g>
      </motion.svg>

      <motion.div
        initial={{ opacity: 0, scale: 0.4, rotate: -12 }}
        animate={{ opacity: 1, scale: 1, rotate: 0 }}
        transition={{ type: "spring", stiffness: 220, damping: 16, delay: 0.3 }}
        whileHover={{ scale: 1.06, rotate: 4 }}
        className="hsi__mark"
      >
        {/* a home outline with a keyhole door, for a rental app */}
        <svg viewBox="0 0 24 24" aria-hidden>
          <motion.path
            d="M4.5 10.4 12 4.5l7.5 5.9V18a1.5 1.5 0 0 1-1.5 1.5H6A1.5 1.5 0 0 1 4.5 18v-7.6Z"
            fill="none"
            stroke="#fff"
            strokeWidth="2"
            strokeLinejoin="round"
            initial={{ pathLength: 0, opacity: 0 }}
            animate={{ pathLength: 1, opacity: 1 }}
            transition={{ duration: 0.9, ease: EASE_OUT, delay: 0.55 }}
          />
          <motion.g
            initial={{ opacity: 0, scale: 0.4 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ type: "spring", stiffness: 300, damping: 18, delay: 0.95 }}
            style={{ transformOrigin: "12px 14px" }}
          >
            <circle cx="12" cy="12.8" r="1.7" fill="#fff" />
            <path d="M11.2 13.6h1.6l.4 3h-2.4l.4-3Z" fill="#fff" />
          </motion.g>
        </svg>
      </motion.div>
    </div>
  );
}

type FieldProps = {
  label: string;
  icon: ReactNode;
  trailing?: ReactNode;
} & Omit<InputHTMLAttributes<HTMLInputElement>, "placeholder">;

function Field({ label, icon, trailing, ...input }: FieldProps) {
  const id = useId();
  return (
    <div className="hsi__field">
      <label htmlFor={id} className="hsi__sr">
        {label}
      </label>
      <span className="hsi__field-icon">{icon}</span>
      <input id={id} required placeholder={label} className="hsi__input" {...input} />
      {trailing && <span className="hsi__trailing">{trailing}</span>}
    </div>
  );
}

function SocialButton({ label, onClick, children }: { label: string; onClick: () => void; children: ReactNode }) {
  return (
    <motion.button
      type="button"
      aria-label={label}
      title={label}
      onClick={onClick}
      whileHover={{ y: -2 }}
      whileTap={{ scale: 0.96, y: 0 }}
      transition={SPRING}
      className="hsi__social"
    >
      {children}
    </motion.button>
  );
}

