const fromTop: Variants = {
  hidden: { opacity: 0, y: -10 },
  show: (delay: number) => ({ opacity: 1, y: 0, transition: { duration: 0.8, ease: EASE, delay } }),
};

const TITLE = "Connecting you to experiences";

