              "--amp": `${(4 + d * 7).toFixed(1)}px`,
              "--w": `calc(var(--plh-unit) * ${((0.55 + d * 0.65) * (portrait ? 0.82 : 1)).toFixed(3)})`,
            } as CSSProperties;
            return (
