  {
    title: "Contact",
    links: [
      { label: "hello@synais.ai", href: "mailto:hello@synais.ai" },
      { label: "+62 21 5555 8888", href: "tel:+622155558888" },
      { label: "Surabaya, Indonesia", href: "#" },
