        d="M15.6 8.6c-.7-1-1.9-1.6-3.4-1.6-2 0-3.4 1-3.4 2.5 0 3.2 7.2 1.7 7.2 5 0 1.6-1.6 2.6-3.7 2.6-1.6 0-2.9-.6-3.7-1.8"
        fill="none"
